insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('692442f3-20d3-54e3-b360-bc750b5ad672', '0e8a54e6-533a-5a46-830e-098e153d93db', 'multiple_choice', 'Increase £60 by 15%.', '[{"id":"A","text":"£69"},{"id":"B","text":"£75"},{"id":"C","text":"£60.15"},{"id":"D","text":"£51"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('692442f3-20d3-54e3-b360-bc750b5ad672', 'A', '15% of £60 is £9 (10% is £6 and 5% is £3). £60 + £9 = £69.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('f9a2f2d5-dfc6-592b-a770-3e3bd838d3eb', '0e8a54e6-533a-5a46-830e-098e153d93db', 'true_false', 'True or false: 0.6 is greater than 5/8.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('f9a2f2d5-dfc6-592b-a770-3e3bd838d3eb', 'B', '5/8 = 0.625, which is greater than 0.6. Converting both to decimals makes the comparison easy.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('2890f594-82d7-5824-9586-54f6afba0c39', '0e8a54e6-533a-5a46-830e-098e153d93db', 'multiple_choice', 'A jacket costs £48 after a 20% discount. What was the original price?', '[{"id":"A","text":"£60"},{"id":"B","text":"£57.60"},{"id":"C","text":"£68"},{"id":"D","text":"£38.40"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('2890f594-82d7-5824-9586-54f6afba0c39', 'A', 'After a 20% discount you pay 80% of the price, so 0.8 × original = £48. Original = £48 ÷ 0.8 = £60. Adding 20% of £48 back on (£57.60) is a common mistake.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('aebcfd30-d1c7-544c-91f3-a114087f0fb1', '0e8a54e6-533a-5a46-830e-098e153d93db', 'multiple_choice', 'Write 0.45 as a fraction in its simplest form.', '[{"id":"A","text":"9/20"},{"id":"B","text":"45/100"},{"id":"C","text":"4/9"},{"id":"D","text":"1/45"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('aebcfd30-d1c7-544c-91f3-a114087f0fb1', 'A', '0.45 = 45/100. Divide top and bottom by their highest common factor, 5, to get 9/20. 45/100 has the right value but isn''t simplified.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('00b5b9b7-9043-5ee6-8a16-90c2d219db49', '0e8a54e6-533a-5a46-830e-098e153d93db', 'short_answer', 'Work out 2/3 of 54.', null, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, accepted_answers, explanation) values ('00b5b9b7-9043-5ee6-8a16-90c2d219db49', array['36']::text[], 'Divide by the denominator, then multiply by the numerator: 54 ÷ 3 = 18, and 18 × 2 = 36.')
on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('2150b98e-3e98-5e6e-b552-68f3aa0101de', '0e8a54e6-533a-5a46-830e-098e153d93db', 'multiple_choice', '£2000 is invested at 3% compound interest per year. How much is it worth after 2 years?', '[{"id":"A","text":"£2121.80"},{"id":"B","text":"£2120.00"},{"id":"C","text":"£2060.00"},{"id":"D","text":"£2180.00"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('2150b98e-3e98-5e6e-b552-68f3aa0101de', 'A', 'Multiply by 1.03 once for each year: £2000 × 1.03² = £2000 × 1.0609 = £2121.80. £2120 would be simple interest, which doesn''t earn interest on interest.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('df71d4d2-1722-5d2e-ae20-a04ba5014f75', '0e8a54e6-533a-5a46-830e-098e153d93db', 'multiple_choice', 'A price is increased by 10% and then the new price is decreased by 10%. What is the overall change?', '[{"id":"A","text":"A 1% decrease"},{"id":"B","text":"No change"},{"id":"C","text":"A 1% increase"},{"id":"D","text":"A 0.1% decrease"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('df71d4d2-1722-5d2e-ae20-a04ba5014f75', 'A', 'Use multipliers: 1.1 × 0.9 = 0.99, which is 99% of the original price, so a 1% decrease. The second 10% is taken from a larger amount.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;

