on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('ca16a832-9a77-5e3a-9fe5-a8cac8dd667e', '8c3a66d3-e9a9-56ee-abc6-2c26be7740d1', 'multiple_choice', 'Factorise x² + 7x + 12.', '[{"id":"A","text":"(x + 3)(x + 4)"},{"id":"B","text":"(x + 2)(x + 6)"},{"id":"C","text":"(x + 1)(x + 12)"},{"id":"D","text":"(x − 3)(x − 4)"}]'::jsonb, 'standard', 'question_bank', true)
