on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('a27a2c28-0d6d-5100-97fc-b289b3200d4d', '8c3a66d3-e9a9-56ee-abc6-2c26be7740d1', 'short_answer', 'Solve 2(x − 4) = 10. Give the value of x.', null, 'standard', 'question_bank', true)
