on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('18f0c944-0eb7-5fda-b65e-e974e21b298e', '8c3a66d3-e9a9-56ee-abc6-2c26be7740d1', 'multiple_choice', 'Solve x² − 5x + 6 = 0.', '[{"id":"A","text":"x = 2 or x = 3"},{"id":"B","text":"x = −2 or x = −3"},{"id":"C","text":"x = 1 or x = 6"},{"id":"D","text":"x = −1 or x = 6"}]'::jsonb, 'challenge', 'question_bank', true)
