-- english-language / Grammar and punctuation
insert into public.topics (id, subject_id, slug, name, description, education_stage, sort_order)
select '29822291-0810-51c2-b6ec-7e88a437f4e4', id, 'grammar-punctuation', 'Grammar and punctuation', 'Sentence types, punctuation and common errors.', 'gcse', 40
from public.subjects where slug = 'english-language'
on conflict (id) do update set name = excluded.name, description = excluded.description;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('97a212b1-3622-5dd4-9c70-70eeb22cdd35', '29822291-0810-51c2-b6ec-7e88a437f4e4', 'multiple_choice', 'Which sentence uses an apostrophe correctly?', '[{"id":"A","text":"The dog wagged it''s tail."},{"id":"B","text":"The dog wagged its tail."},{"id":"C","text":"The dog''s wagged it''s tail."},{"id":"D","text":"The dogs wagged it''s tails."}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('97a212b1-3622-5dd4-9c70-70eeb22cdd35', 'B', '"Its" (no apostrophe) means belonging to it. "It''s" always means "it is" or "it has".')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('480f748c-a869-5e84-859b-7255c658dc4d', '29822291-0810-51c2-b6ec-7e88a437f4e4', 'multiple_choice', 'Which of these words is a conjunction?', '[{"id":"A","text":"because"},{"id":"B","text":"quickly"},{"id":"C","text":"beautiful"},{"id":"D","text":"under"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('480f748c-a869-5e84-859b-7255c658dc4d', 'A', 'Conjunctions join clauses, for example "because", "and", "but". "Quickly" is an adverb, "beautiful" an adjective and "under" a preposition.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('6689aecd-9483-579d-9e57-f70a3e684bb6', '29822291-0810-51c2-b6ec-7e88a437f4e4', 'true_false', 'True or false: a semicolon can join two closely related main clauses.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('6689aecd-9483-579d-9e57-f70a3e684bb6', 'A', 'Each side of the semicolon could stand alone as a sentence, for example: "It was late; we went home."')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('e98c190c-d8fe-5d95-929d-a170999864b8', '29822291-0810-51c2-b6ec-7e88a437f4e4', 'multiple_choice', 'Which of these is a complex sentence?', '[{"id":"A","text":"Although it was raining, we went for a walk."},{"id":"B","text":"It was raining."},{"id":"C","text":"It was raining and we went for a walk."},{"id":"D","text":"Rain!"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('e98c190c-d8fe-5d95-929d-a170999864b8', 'A', 'A complex sentence has a main clause and a subordinate clause. "Although it was raining" can''t stand alone. The third option is compound: two main clauses joined by "and".')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('b5861fff-09b7-5091-9a35-2dc09ba4ddc8', '29822291-0810-51c2-b6ec-7e88a437f4e4', 'multiple_choice', 'Choose the correct word: "___ going to the cinema tonight."', '[{"id":"A","text":"There"},{"id":"B","text":"Their"},{"id":"C","text":"They''re"},{"id":"D","text":"Thier"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('b5861fff-09b7-5091-9a35-2dc09ba4ddc8', 'C', '"They''re" is short for "they are". "Their" shows belonging and "there" refers to a place. "Thier" is a misspelling.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('2900a0f8-3228-554f-890e-0e2c96787cd5', '29822291-0810-51c2-b6ec-7e88a437f4e4', 'short_answer', 'Which punctuation mark introduces a list or an explanation after a complete sentence?', null, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, accepted_answers, explanation) values ('2900a0f8-3228-554f-890e-0e2c96787cd5', array['colon', 'a colon', ':']::text[], 'A colon (:) introduces what follows, for example: "You need three things: a pen, a ruler and a calculator."')
on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('8e9e33ce-ddae-54ee-8f8f-e67701038d3f', '29822291-0810-51c2-b6ec-7e88a437f4e4', 'multiple_choice', 'Which sentence is in the passive voice?', '[{"id":"A","text":"The window was broken by the ball."},{"id":"B","text":"The ball broke the window."},{"id":"C","text":"The boy kicked the ball at the window."},{"id":"D","text":"The ball will break the window."}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('8e9e33ce-ddae-54ee-8f8f-e67701038d3f', 'A', 'In the passive voice the thing affected becomes the subject: "The window was broken by the ball". The others are active: the doer comes first.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('eca717b8-c249-5769-bb9e-36e6c76d7764', '29822291-0810-51c2-b6ec-7e88a437f4e4', 'multiple_choice', 'Which sentence contains a comma splice?', '[{"id":"A","text":"I love reading, it helps me relax."},{"id":"B","text":"I love reading because it helps me relax."},{"id":"C","text":"I love reading; it helps me relax."},{"id":"D","text":"Reading, which I love, helps me relax."}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('eca717b8-c249-5769-bb9e-36e6c76d7764', 'A', 'A comma splice joins two main clauses with only a comma. Fix it with a full stop, a semicolon or a conjunction, as in the other options.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;

