from public.subjects where slug = 'english-literature'
on conflict (id) do update set name = excluded.name, description = excluded.description;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('2ff5ef09-d681-55d1-9b84-fd6fa485cbca', '7bf87ce2-88be-548b-a0c3-ffc2bcf630c6', 'multiple_choice', 'Who first predicts that Macbeth will become king?', '[{"id":"A","text":"The three witches"},{"id":"B","text":"Lady Macbeth"},{"id":"C","text":"Banquo"},{"id":"D","text":"King Duncan"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('2ff5ef09-d681-55d1-9b84-fd6fa485cbca', 'A', 'In Act 1 Scene 3 the witches greet Macbeth as Thane of Glamis, Thane of Cawdor and future king.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('12a6f4a2-ed0f-5eeb-91d7-46ff268ebcd0', '7bf87ce2-88be-548b-a0c3-ffc2bcf630c6', 'multiple_choice', 'Who does Macbeth murder in order to become king?', '[{"id":"A","text":"Duncan"},{"id":"B","text":"Banquo"},{"id":"C","text":"Malcolm"},{"id":"D","text":"Macduff"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('12a6f4a2-ed0f-5eeb-91d7-46ff268ebcd0', 'A', 'Macbeth kills King Duncan while he is a guest at Macbeth''s castle. He later has Banquo murdered to protect his position.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('ab5fde3f-3d7c-54fd-b1e7-b70f23e410bc', '7bf87ce2-88be-548b-a0c3-ffc2bcf630c6', 'true_false', 'True or false: Banquo''s ghost appears at Macbeth''s banquet.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('ab5fde3f-3d7c-54fd-b1e7-b70f23e410bc', 'A', 'In Act 3 Scene 4 only Macbeth can see the ghost, and his reaction alarms his guests.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('17b3e7d9-c189-5ea8-8e33-74f324e0b5bc', '7bf87ce2-88be-548b-a0c3-ffc2bcf630c6', 'multiple_choice', 'Which character says "Out, damned spot!"?', '[{"id":"A","text":"Lady Macbeth"},{"id":"B","text":"Macbeth"},{"id":"C","text":"The Porter"},{"id":"D","text":"Lady Macduff"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('17b3e7d9-c189-5ea8-8e33-74f324e0b5bc', 'A', 'Lady Macbeth says it while sleepwalking in Act 5 Scene 1, trying to wash imaginary blood from her hands.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('9ea3b7ba-9723-57ab-a7d0-edbf973cfb64', '7bf87ce2-88be-548b-a0c3-ffc2bcf630c6', 'multiple_choice', 'What does Lady Macbeth''s sleepwalking scene mainly show?', '[{"id":"A","text":"Her guilt"},{"id":"B","text":"Her growing ambition"},{"id":"C","text":"Her loyalty to Duncan"},{"id":"D","text":"Her fear of the witches"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('9ea3b7ba-9723-57ab-a7d0-edbf973cfb64', 'A', 'Earlier she said "a little water clears us of this deed". Now she can''t stop scrubbing, which shows that guilt has overwhelmed her.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('952f8e49-e9e9-5e94-ac39-4c889054d1ef', '7bf87ce2-88be-548b-a0c3-ffc2bcf630c6', 'short_answer', 'Who kills Macbeth at the end of the play?', null, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, accepted_answers, explanation) values ('952f8e49-e9e9-5e94-ac39-4c889054d1ef', array['macduff']::text[], 'Macduff, who was "from his mother''s womb untimely ripped", fulfils the witches'' prophecy and kills Macbeth.')
on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('231cfea9-98c4-5010-9dff-843f9fd80d81', '7bf87ce2-88be-548b-a0c3-ffc2bcf630c6', 'multiple_choice', 'The witches'' line "Fair is foul, and foul is fair" introduces which key theme?', '[{"id":"A","text":"Appearance versus reality"},{"id":"B","text":"Love and marriage"},{"id":"C","text":"Childhood and innocence"},{"id":"D","text":"Nature and the seasons"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('231cfea9-98c4-5010-9dff-843f9fd80d81', 'A', 'The paradox suggests things are not what they seem, which echoes through the play, for example in Macbeth hiding murder behind a loyal face.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('72cfaaeb-b03b-58b0-8940-828a7d695f53', '7bf87ce2-88be-548b-a0c3-ffc2bcf630c6', 'multiple_choice', 'Why was the play''s subject matter significant to King James I?', '[{"id":"A","text":"He was fascinated by witchcraft and was said to be descended from Banquo"},{"id":"B","text":"He had written the first version of the play"},{"id":"C","text":"He had just banned the theatre in Scotland"},{"id":"D","text":"He believed witches were harmless"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('72cfaaeb-b03b-58b0-8940-828a7d695f53', 'A', 'James I wrote a book on witchcraft (Daemonologie) and was believed to be Banquo''s descendant, which may explain Banquo''s positive portrayal.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;

