insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('7b5fb6b7-217d-5971-96ce-014f9a0bd866', '942ee587-96e4-561e-8442-fe69a89c5635', 'multiple_choice', 'Which ghost visits Scrooge first, to warn him?', '[{"id":"A","text":"Jacob Marley"},{"id":"B","text":"The Ghost of Christmas Past"},{"id":"C","text":"The Ghost of Christmas Present"},{"id":"D","text":"The Ghost of Christmas Yet to Come"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('7b5fb6b7-217d-5971-96ce-014f9a0bd866', 'A', 'Marley, Scrooge''s dead business partner, appears first and warns him that three spirits will visit.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('ab740423-7f63-5d11-bd80-15b981097311', '942ee587-96e4-561e-8442-fe69a89c5635', 'multiple_choice', 'Who is Scrooge''s clerk?', '[{"id":"A","text":"Bob Cratchit"},{"id":"B","text":"Fred"},{"id":"C","text":"Fezziwig"},{"id":"D","text":"Jacob Marley"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('ab740423-7f63-5d11-bd80-15b981097311', 'A', 'Bob Cratchit works for Scrooge for low pay in a cold office. Fred is Scrooge''s nephew.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('99b35306-a842-5ed9-a65f-06639531e8be', '942ee587-96e4-561e-8442-fe69a89c5635', 'true_false', 'True or false: Tiny Tim is Bob Cratchit''s son.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('99b35306-a842-5ed9-a65f-06639531e8be', 'A', 'Tiny Tim is Bob''s youngest son. His illness and goodness move Scrooge to change.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('aee27493-aed4-516a-aa10-5c46fdb617df', '942ee587-96e4-561e-8442-fe69a89c5635', 'multiple_choice', 'What is Marley''s ghost wearing?', '[{"id":"A","text":"A chain made of cash-boxes, keys and padlocks"},{"id":"B","text":"A crown of holly"},{"id":"C","text":"A long black hooded robe"},{"id":"D","text":"A green robe trimmed with fur"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('aee27493-aed4-516a-aa10-5c46fdb617df', 'A', 'The chain represents the greed Marley forged in life. The green robe belongs to the Ghost of Christmas Present.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('c5d4f9f7-b3c8-587c-b77f-c487246ac216', '942ee587-96e4-561e-8442-fe69a89c5635', 'multiple_choice', 'Which two children hide under the Ghost of Christmas Present''s robe?', '[{"id":"A","text":"Ignorance and Want"},{"id":"B","text":"Hope and Charity"},{"id":"C","text":"Past and Future"},{"id":"D","text":"Greed and Pride"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('c5d4f9f7-b3c8-587c-b77f-c487246ac216', 'A', 'Ignorance and Want represent the neglected poor. The ghost warns that Ignorance is the most dangerous.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('769cc848-89b6-5b29-85dc-9811d0f84279', '942ee587-96e4-561e-8442-fe69a89c5635', 'short_answer', 'Who was Scrooge''s kind first employer, shown hosting a Christmas party?', null, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, accepted_answers, explanation) values ('769cc848-89b6-5b29-85dc-9811d0f84279', array['fezziwig', 'mr fezziwig', 'old fezziwig']::text[], 'Old Fezziwig shows how a generous employer can make people happy, a contrast with Scrooge''s treatment of Bob.')
on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('e92e80a8-24ab-5aab-8625-029eef186d60', '942ee587-96e4-561e-8442-fe69a89c5635', 'multiple_choice', 'Which statement best sums up Dickens'' message about society?', '[{"id":"A","text":"The wealthy have a responsibility to help the poor"},{"id":"B","text":"Poverty is the fault of the poor"},{"id":"C","text":"Ghost stories are only for children"},{"id":"D","text":"Businesses should never close at Christmas"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('e92e80a8-24ab-5aab-8625-029eef186d60', 'A', 'Dickens wrote the novella in 1843 to challenge attitudes to poverty. Scrooge''s change shows that the rich can and should help others.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('e5f76018-4f11-5185-9f3d-054030ffdaec', '942ee587-96e4-561e-8442-fe69a89c5635', 'multiple_choice', 'Which spirit never speaks to Scrooge?', '[{"id":"A","text":"The Ghost of Christmas Yet to Come"},{"id":"B","text":"The Ghost of Christmas Past"},{"id":"C","text":"The Ghost of Christmas Present"},{"id":"D","text":"Jacob Marley"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('e5f76018-4f11-5185-9f3d-054030ffdaec', 'A', 'The final spirit only points, which makes it more frightening and leaves Scrooge to face his future himself.')
