insert into public.question_answers (question_id, correct_option, explanation) values ('984fa65b-f35a-555c-9a25-c544588c5a58', 'A', 'The nucleus contains DNA in chromosomes. The membrane controls what enters and leaves; ribosomes make proteins.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('4206502a-9586-508d-9128-3a5633349ecd', 'bbd5bcaa-f8d2-57a5-9c35-c2747acf2fa3', 'multiple_choice', 'Which structure is found in plant cells but not in animal cells?', '[{"id":"A","text":"Cell wall"},{"id":"B","text":"Nucleus"},{"id":"C","text":"Cell membrane"},{"id":"D","text":"Mitochondria"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('4206502a-9586-508d-9128-3a5633349ecd', 'A', 'Plant cells have a cellulose cell wall (and often chloroplasts and a permanent vacuole). Animal cells have the other three too.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('d487ac5d-0f84-53b4-bc3e-b2e1f6c05b5b', 'bbd5bcaa-f8d2-57a5-9c35-c2747acf2fa3', 'true_false', 'True or false: bacterial cells have a nucleus.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('d487ac5d-0f84-53b4-bc3e-b2e1f6c05b5b', 'B', 'Bacteria are prokaryotic cells. Their genetic material is a single loop of DNA in the cytoplasm, sometimes with small rings called plasmids.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('d476bd19-96e3-5d2a-91b3-1902b011f98e', 'bbd5bcaa-f8d2-57a5-9c35-c2747acf2fa3', 'multiple_choice', 'Where in a cell does protein synthesis take place?', '[{"id":"A","text":"Ribosomes"},{"id":"B","text":"Mitochondria"},{"id":"C","text":"Nucleus"},{"id":"D","text":"Vacuole"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('d476bd19-96e3-5d2a-91b3-1902b011f98e', 'A', 'Ribosomes join amino acids together to make proteins. Mitochondria are where aerobic respiration happens.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('c7524987-3c73-5a07-a4c8-873ad382eb60', 'bbd5bcaa-f8d2-57a5-9c35-c2747acf2fa3', 'multiple_choice', 'Which statement describes diffusion?', '[{"id":"A","text":"The net movement of particles from a higher to a lower concentration"},{"id":"B","text":"The movement of water only, through a membrane"},{"id":"C","text":"Movement against a concentration gradient using energy"},{"id":"D","text":"The breakdown of glucose to release energy"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('c7524987-3c73-5a07-a4c8-873ad382eb60', 'A', 'Diffusion is passive: particles spread out down a concentration gradient with no energy needed from respiration.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('ad92c9cf-f981-5e39-9f8e-1bd68ab581b3', 'bbd5bcaa-f8d2-57a5-9c35-c2747acf2fa3', 'short_answer', 'Name the process in which water moves across a partially permeable membrane from a dilute solution to a more concentrated one.', null, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, accepted_answers, explanation) values ('ad92c9cf-f981-5e39-9f8e-1bd68ab581b3', array['osmosis']::text[], 'Osmosis is the diffusion of water across a partially permeable membrane, from a dilute solution to a more concentrated solution.')
on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('f9dd959b-36a1-561c-aa08-1e68ab76cb2d', 'bbd5bcaa-f8d2-57a5-9c35-c2747acf2fa3', 'multiple_choice', 'How does active transport differ from diffusion?', '[{"id":"A","text":"It needs energy from respiration and moves substances against a concentration gradient"},{"id":"B","text":"It only moves water"},{"id":"C","text":"It is faster because it needs no energy"},{"id":"D","text":"It only happens in plant cells"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('f9dd959b-36a1-561c-aa08-1e68ab76cb2d', 'A', 'Active transport uses energy from respiration to move substances from a lower to a higher concentration, for example mineral ions into root hair cells.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('ccf6a8b7-6701-553f-a613-3347363b71ad', 'bbd5bcaa-f8d2-57a5-9c35-c2747acf2fa3', 'multiple_choice', 'A cell is 0.02 mm long. In a drawing it is 40 mm long. What is the magnification?', '[{"id":"A","text":"× 2000"},{"id":"B","text":"× 800"},{"id":"C","text":"× 200"},{"id":"D","text":"× 20 000"}]'::jsonb, 'challenge', 'question_bank', true)
