insert into public.question_answers (question_id, correct_option, explanation) values ('ccf6a8b7-6701-553f-a613-3347363b71ad', 'A', 'Magnification = image size ÷ real size = 40 ÷ 0.02 = 2000. Both measurements must be in the same units.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;

