insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('26cc3616-62fe-5ade-afd6-f8286f55fcb3', '72545cd9-2540-5282-8e5c-da18038e5507', 'multiple_choice', 'What type of pathogen causes measles?', '[{"id":"A","text":"A virus"},{"id":"B","text":"A bacterium"},{"id":"C","text":"A fungus"},{"id":"D","text":"A protist"}]'::jsonb, 'foundation', 'question_bank', true)
