insert into public.question_answers (question_id, correct_option, explanation) values ('26cc3616-62fe-5ade-afd6-f8286f55fcb3', 'A', 'Measles is a viral disease spread by droplets from coughs and sneezes. Vaccination has made it much less common.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('9d6cc323-c405-5a70-9e7f-1f3ad0028035', '72545cd9-2540-5282-8e5c-da18038e5507', 'multiple_choice', 'Which of these is a job of white blood cells?', '[{"id":"A","text":"Engulfing and digesting pathogens"},{"id":"B","text":"Carrying oxygen"},{"id":"C","text":"Helping blood to clot"},{"id":"D","text":"Digesting food"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('9d6cc323-c405-5a70-9e7f-1f3ad0028035', 'A', 'Some white blood cells engulf pathogens (phagocytosis); others make antibodies or antitoxins. Red blood cells carry oxygen and platelets help clotting.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('0c9b20ad-3c62-5f1d-b7f4-dc7876820eb0', '72545cd9-2540-5282-8e5c-da18038e5507', 'true_false', 'True or false: antibiotics can be used to kill viruses.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('0c9b20ad-3c62-5f1d-b7f4-dc7876820eb0', 'B', 'Antibiotics kill bacteria. Viruses live inside cells, so antibiotics don''t work on them.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('ee52c449-c560-532d-a180-6bf6397e316e', '72545cd9-2540-5282-8e5c-da18038e5507', 'multiple_choice', 'What causes malaria, and how is it spread?', '[{"id":"A","text":"A protist, spread by mosquitoes"},{"id":"B","text":"A virus, spread in water"},{"id":"C","text":"A bacterium, spread by touch"},{"id":"D","text":"A fungus, spread by spores in the air"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('ee52c449-c560-532d-a180-6bf6397e316e', 'A', 'Malaria is caused by a protist. Mosquitoes act as vectors, passing it on when they feed on blood.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('76ba9a28-e5c0-5f28-af64-ef96639d9498', '72545cd9-2540-5282-8e5c-da18038e5507', 'multiple_choice', 'How does a vaccine protect a person from a disease?', '[{"id":"A","text":"It contains dead or inactive pathogens that make white blood cells produce antibodies, so the body responds quickly to future infection"},{"id":"B","text":"It kills any bacteria already in the body"},{"id":"C","text":"It contains antibiotics that last for years"},{"id":"D","text":"It makes red blood cells carry more oxygen"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('76ba9a28-e5c0-5f28-af64-ef96639d9498', 'A', 'The vaccine triggers an immune response without causing the disease. Memory cells then allow a fast response if the real pathogen enters the body.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('e9922098-6e2c-5c4d-a575-a49eaf865ce0', '72545cd9-2540-5282-8e5c-da18038e5507', 'short_answer', 'What are the proteins called that white blood cells make to target specific antigens?', null, 'standard', 'question_bank', true)
