insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('2f70ac3b-aa49-58cf-93c6-32fafa6bb0bc', '72545cd9-2540-5282-8e5c-da18038e5507', 'multiple_choice', 'Why should patients finish a full course of antibiotics?', '[{"id":"A","text":"To kill all the bacteria, so resistant ones are less likely to survive and spread"},{"id":"B","text":"Because antibiotics also kill viruses"},{"id":"C","text":"To build up antibodies against the antibiotic"},{"id":"D","text":"Because the first doses don''t do anything"}]'::jsonb, 'challenge', 'question_bank', true)
