insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('bec30f55-24d2-56a1-be62-e8df20625000', 'a94514ae-2c74-5a65-95f2-f28a6ce1e701', 'multiple_choice', 'Which particles are found in the nucleus of an atom?', '[{"id":"A","text":"Protons and neutrons"},{"id":"B","text":"Electrons only"},{"id":"C","text":"Protons and electrons"},{"id":"D","text":"Neutrons and electrons"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('bec30f55-24d2-56a1-be62-e8df20625000', 'A', 'The nucleus contains protons and neutrons. Electrons are found in shells around the nucleus.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('f71932a7-5410-5728-9877-349bc84fb190', 'a94514ae-2c74-5a65-95f2-f28a6ce1e701', 'true_false', 'True or false: isotopes of an element have the same number of protons but different numbers of neutrons.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('f71932a7-5410-5728-9877-349bc84fb190', 'A', 'The number of protons defines the element. Isotopes differ only in their neutrons, so they have different mass numbers.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('65da42b0-91cd-5beb-a5b4-fb9993137578', 'a94514ae-2c74-5a65-95f2-f28a6ce1e701', 'multiple_choice', 'Fluorine has atomic number 9 and mass number 19. How many neutrons are in a fluorine atom?', '[{"id":"A","text":"10"},{"id":"B","text":"9"},{"id":"C","text":"19"},{"id":"D","text":"28"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('65da42b0-91cd-5beb-a5b4-fb9993137578', 'A', 'Neutrons = mass number − atomic number = 19 − 9 = 10.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('406f3f1b-b5a2-5225-be48-57a76f5aadf5', 'a94514ae-2c74-5a65-95f2-f28a6ce1e701', 'multiple_choice', 'Sodium has 11 electrons. What is its electronic structure?', '[{"id":"A","text":"2, 8, 1"},{"id":"B","text":"2, 9"},{"id":"C","text":"8, 2, 1"},{"id":"D","text":"2, 1, 8"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('406f3f1b-b5a2-5225-be48-57a76f5aadf5', 'A', 'Fill shells from the inside: 2 in the first, up to 8 in the second, and the remaining 1 in the third.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('4aa2958c-eb57-5293-9d76-963029b6fa4b', 'a94514ae-2c74-5a65-95f2-f28a6ce1e701', 'short_answer', 'Before the nuclear model, which model described the atom as a ball of positive charge with electrons embedded in it?', null, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, accepted_answers, explanation) values ('4aa2958c-eb57-5293-9d76-963029b6fa4b', array['plum pudding', 'plum pudding model', 'the plum pudding model', 'plum-pudding model']::text[], 'J.J. Thomson proposed the plum pudding model after discovering the electron. It was replaced after the alpha scattering experiment.')
on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('98404792-198e-5c3d-93ec-1e446593d694', 'a94514ae-2c74-5a65-95f2-f28a6ce1e701', 'multiple_choice', 'Chlorine is 75% chlorine-35 and 25% chlorine-37. What is its relative atomic mass?', '[{"id":"A","text":"35.5"},{"id":"B","text":"36.0"},{"id":"C","text":"35.0"},{"id":"D","text":"37.0"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('98404792-198e-5c3d-93ec-1e446593d694', 'A', 'Use a weighted mean: (35 × 75 + 37 × 25) ÷ 100 = (2625 + 925) ÷ 100 = 35.5.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('e11a0e58-9918-5cc3-8a18-91550427f93e', 'a94514ae-2c74-5a65-95f2-f28a6ce1e701', 'multiple_choice', 'What did the alpha particle scattering experiment show?', '[{"id":"A","text":"Most of an atom is empty space, with a tiny, dense, positive nucleus"},{"id":"B","text":"Atoms are solid spheres that can''t be divided"},{"id":"C","text":"Electrons orbit at fixed distances"},{"id":"D","text":"Neutrons exist in the nucleus"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('e11a0e58-9918-5cc3-8a18-91550427f93e', 'A', 'Most alpha particles passed straight through, but a few were deflected back, which showed mass and positive charge are concentrated in a small nucleus.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;

