insert into public.question_answers (question_id, correct_option, explanation) values ('61d9bd70-20c7-57ff-a418-fe5448fd580b', 'A', 'Sodium (a metal) transfers an electron to chlorine (a non-metal), forming oppositely charged ions held by ionic bonds.')
