insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('79f78bad-df18-5ef1-9e3a-491b18a51fa9', 'a3c5ac74-d828-52dc-803f-282f01d9bd3b', 'multiple_choice', 'What happens to the total resistance of a circuit when another resistor is added in parallel?', '[{"id":"A","text":"It decreases"},{"id":"B","text":"It increases"},{"id":"C","text":"It stays the same"},{"id":"D","text":"It becomes zero"}]'::jsonb, 'challenge', 'question_bank', true)
