insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('67df0f7d-a8df-5ae8-8f05-b75575930f87', '8a3c66b2-1c52-5046-8bd0-50ea27b2fa4f', 'multiple_choice', 'Which of these was one of the four humours in ancient and medieval medicine?', '[{"id":"A","text":"Black bile"},{"id":"B","text":"Plasma"},{"id":"C","text":"Adrenaline"},{"id":"D","text":"Insulin"}]'::jsonb, 'foundation', 'question_bank', true)
