insert into public.question_answers (question_id, correct_option, explanation) values ('67df0f7d-a8df-5ae8-8f05-b75575930f87', 'A', 'The four humours were blood, phlegm, yellow bile and black bile. Illness was thought to come from an imbalance between them.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('883f8970-6b70-5ea6-9096-8c61494df746', '8a3c66b2-1c52-5046-8bd0-50ea27b2fa4f', 'multiple_choice', 'Who developed a vaccine against smallpox in 1796?', '[{"id":"A","text":"Edward Jenner"},{"id":"B","text":"Louis Pasteur"},{"id":"C","text":"Joseph Lister"},{"id":"D","text":"Alexander Fleming"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('883f8970-6b70-5ea6-9096-8c61494df746', 'A', 'Jenner noticed milkmaids who caught cowpox didn''t catch smallpox, and used cowpox to vaccinate a boy, James Phipps.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('3bf5d3d7-65e8-5185-9de3-5592d152c26e', '8a3c66b2-1c52-5046-8bd0-50ea27b2fa4f', 'true_false', 'True or false: Alexander Fleming discovered penicillin in 1928.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('3bf5d3d7-65e8-5185-9de3-5592d152c26e', 'A', 'Fleming noticed mould killing bacteria on a culture plate in 1928, but he could not produce penicillin in large amounts.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('9d1559a7-2b54-5830-a90d-ebcdd0fcc4ba', '8a3c66b2-1c52-5046-8bd0-50ea27b2fa4f', 'multiple_choice', 'Louis Pasteur is best known for which idea, published in 1861?', '[{"id":"A","text":"Germ theory"},{"id":"B","text":"The Theory of the Four Humours"},{"id":"C","text":"Antiseptic surgery"},{"id":"D","text":"Blood circulation"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('9d1559a7-2b54-5830-a90d-ebcdd0fcc4ba', 'A', 'Pasteur''s germ theory showed that microbes cause decay and disease, replacing ideas such as spontaneous generation.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('84fec605-81bd-53eb-8c8e-fe07542ad516', '8a3c66b2-1c52-5046-8bd0-50ea27b2fa4f', 'multiple_choice', 'Who first used chloroform as an anaesthetic, in 1847?', '[{"id":"A","text":"James Simpson"},{"id":"B","text":"Joseph Lister"},{"id":"C","text":"John Snow"},{"id":"D","text":"Florence Nightingale"}]'::jsonb, 'standard', 'question_bank', true)
