on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('a1469894-2603-5921-b319-0d890098a4fc', '8a3c66b2-1c52-5046-8bd0-50ea27b2fa4f', 'multiple_choice', 'Why was the Great Stink of 1858 significant for public health?', '[{"id":"A","text":"It pushed Parliament to fund Bazalgette''s new sewer system for London"},{"id":"B","text":"It proved germ theory correct"},{"id":"C","text":"It led to the creation of the NHS"},{"id":"D","text":"It ended the use of anaesthetics"}]'::jsonb, 'challenge', 'question_bank', true)
