on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('21f000f6-1392-5d3a-90a9-528c9255b4ed', '8a3c66b2-1c52-5046-8bd0-50ea27b2fa4f', 'multiple_choice', 'What was Florey and Chain''s role in the story of penicillin?', '[{"id":"A","text":"They purified it and showed it could treat infections, leading to mass production in the 1940s"},{"id":"B","text":"They discovered the mould by accident"},{"id":"C","text":"They invented the first vaccine"},{"id":"D","text":"They proved that bad air caused disease"}]'::jsonb, 'challenge', 'question_bank', true)
