insert into public.question_answers (question_id, correct_option, explanation) values ('b701bff4-0196-53cb-8d47-78da9f0e0bd9', 'A', 'In 1923 prices rose so fast that money became almost worthless, partly because the government printed money after the French occupied the Ruhr.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('8b4c82ea-b2d8-5b77-9fb8-f8ce49d473fc', 'de0ecb39-7ef5-501e-b3d8-db11119aab6c', 'multiple_choice', 'Which event in February 1933 did the Nazis use as an excuse to arrest communists?', '[{"id":"A","text":"The Reichstag Fire"},{"id":"B","text":"The Munich Putsch"},{"id":"C","text":"The Night of the Long Knives"},{"id":"D","text":"Kristallnacht"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('8b4c82ea-b2d8-5b77-9fb8-f8ce49d473fc', 'A', 'A Dutch communist was blamed for the fire. Hitler used it to persuade Hindenburg to pass emergency decrees.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('e1381ae3-5eb8-5891-8854-cab0ad2d88d8', 'de0ecb39-7ef5-501e-b3d8-db11119aab6c', 'multiple_choice', 'What did the Enabling Act of March 1933 allow Hitler to do?', '[{"id":"A","text":"Pass laws without the approval of the Reichstag"},{"id":"B","text":"Become President as well as Chancellor"},{"id":"C","text":"Leave the League of Nations"},{"id":"D","text":"Join with Austria"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('e1381ae3-5eb8-5891-8854-cab0ad2d88d8', 'A', 'The Enabling Act gave Hitler''s government the power to make laws for four years without the Reichstag, laying the ground for dictatorship.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('1ab59da5-53e3-5216-87a4-dfae86157065', 'de0ecb39-7ef5-501e-b3d8-db11119aab6c', 'short_answer', 'What name is given to the events of June 1934, when Hitler had Ernst Röhm and other SA leaders killed?', null, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, accepted_answers, explanation) values ('1ab59da5-53e3-5216-87a4-dfae86157065', array['night of the long knives', 'the night of the long knives']::text[], 'In the Night of the Long Knives, Hitler removed rivals in the SA and won the support of the army.')
on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('f6650060-5d18-5142-b974-2ce45d0bb753', 'de0ecb39-7ef5-501e-b3d8-db11119aab6c', 'multiple_choice', 'What did Article 48 of the Weimar Constitution allow?', '[{"id":"A","text":"The President to rule by decree in an emergency"},{"id":"B","text":"The Chancellor to ban all other parties"},{"id":"C","text":"Women to vote for the first time"},{"id":"D","text":"Germany to rebuild its army"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('f6650060-5d18-5142-b974-2ce45d0bb753', 'A', 'Article 48 let the President bypass the Reichstag in an emergency. It was used heavily from 1930, weakening democracy.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('374d21ab-f488-57d0-b579-401c964afe03', 'de0ecb39-7ef5-501e-b3d8-db11119aab6c', 'multiple_choice', 'How did Gustav Stresemann help Germany''s economy recover after 1923?', '[{"id":"A","text":"He introduced a new currency, the Rentenmark, and agreed the Dawes Plan for loans and reparations"},{"id":"B","text":"He stopped paying all reparations"},{"id":"C","text":"He ended the Weimar Republic"},{"id":"D","text":"He took Germany out of the League of Nations"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('374d21ab-f488-57d0-b579-401c964afe03', 'A', 'The Rentenmark ended hyperinflation, and the 1924 Dawes Plan brought US loans and lower yearly reparation payments.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;

-- geography / Natural hazards
insert into public.topics (id, subject_id, slug, name, description, education_stage, sort_order)
select 'ecd2c101-e723-5ebd-a8c1-6dc129f7b045', id, 'natural-hazards', 'Natural hazards', 'Plate tectonics, earthquakes, volcanoes and tropical storms.', 'gcse', 170
from public.subjects where slug = 'geography'
on conflict (id) do update set name = excluded.name, description = excluded.description;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('75f10318-fa80-50d5-b521-8f5aaa1c3cad', 'ecd2c101-e723-5ebd-a8c1-6dc129f7b045', 'multiple_choice', 'At which type of plate margin do plates move apart?', '[{"id":"A","text":"Constructive"},{"id":"B","text":"Destructive"},{"id":"C","text":"Conservative"},{"id":"D","text":"Collision"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('75f10318-fa80-50d5-b521-8f5aaa1c3cad', 'A', 'At constructive margins plates move apart and magma rises to form new crust, as at the Mid-Atlantic Ridge.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('b87ea107-c86a-5ebb-a13e-33d5c4694c24', 'ecd2c101-e723-5ebd-a8c1-6dc129f7b045', 'multiple_choice', 'Which instrument is used to detect and record earthquakes?', '[{"id":"A","text":"Seismometer"},{"id":"B","text":"Barometer"},{"id":"C","text":"Anemometer"},{"id":"D","text":"Thermometer"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('b87ea107-c86a-5ebb-a13e-33d5c4694c24', 'A', 'A seismometer records ground shaking. A barometer measures air pressure and an anemometer measures wind speed.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('a82f2e98-93e6-5b6a-8159-030f9b7062e6', 'ecd2c101-e723-5ebd-a8c1-6dc129f7b045', 'true_false', 'True or false: volcanoes can form at constructive plate margins.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('a82f2e98-93e6-5b6a-8159-030f9b7062e6', 'A', 'Magma rises where plates move apart, forming gently sloping shield volcanoes, such as those in Iceland.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('ef6e924a-bfb9-5091-9663-53dac7200737', 'ecd2c101-e723-5ebd-a8c1-6dc129f7b045', 'multiple_choice', 'Why do many people choose to live near volcanoes?', '[{"id":"A","text":"Volcanic soils are very fertile for farming"},{"id":"B","text":"Volcanoes never erupt more than once"},{"id":"C","text":"Land near volcanoes is always flat"},{"id":"D","text":"There are no earthquakes near volcanoes"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('ef6e924a-bfb9-5091-9663-53dac7200737', 'A', 'Fertile soils, tourism, geothermal energy and minerals all attract people, despite the risk of eruptions.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('6b0f8303-e814-5b9f-8b08-391606215f3b', 'ecd2c101-e723-5ebd-a8c1-6dc129f7b045', 'multiple_choice', 'What happens at a conservative plate margin?', '[{"id":"A","text":"Plates slide past each other"},{"id":"B","text":"Plates move apart"},{"id":"C","text":"An oceanic plate sinks under a continental plate"},{"id":"D","text":"Plates stop moving completely"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('6b0f8303-e814-5b9f-8b08-391606215f3b', 'A', 'At conservative margins plates slide past each other. Friction builds up and is released as earthquakes, as on the San Andreas Fault.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('cfcf2fa5-30c2-5e8a-867c-06aad1ecec2b', 'ecd2c101-e723-5ebd-a8c1-6dc129f7b045', 'short_answer', 'What is the point on the Earth''s surface directly above the focus of an earthquake called?', null, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, accepted_answers, explanation) values ('cfcf2fa5-30c2-5e8a-867c-06aad1ecec2b', array['epicentre', 'epicenter', 'the epicentre', 'the epicenter']::text[], 'The focus is where the earthquake starts underground; the epicentre is directly above it, where shaking is usually strongest.')
on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('9551112c-6fdf-5900-8e4c-3ab8776ae7c2', 'ecd2c101-e723-5ebd-a8c1-6dc129f7b045', 'multiple_choice', 'Why do earthquakes in lower-income countries often cause more deaths than similar earthquakes in higher-income countries?', '[{"id":"A","text":"Buildings are less likely to be earthquake-resistant and emergency services may be less well prepared"},{"id":"B","text":"Earthquakes there are always stronger"},{"id":"C","text":"People there live further from plate margins"},{"id":"D","text":"Seismometers don''t work there"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('9551112c-6fdf-5900-8e4c-3ab8776ae7c2', 'A', 'Building standards, preparation, emergency response and healthcare all reduce deaths. These often depend on money and resources.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('c1638cc3-7639-5ada-8d62-b0040c517507', 'ecd2c101-e723-5ebd-a8c1-6dc129f7b045', 'multiple_choice', 'Tropical storms usually form over oceans with a surface temperature of at least about…', '[{"id":"A","text":"27 °C"},{"id":"B","text":"10 °C"},{"id":"C","text":"17 °C"},{"id":"D","text":"37 °C"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('c1638cc3-7639-5ada-8d62-b0040c517507', 'A', 'Warm water of about 27 °C or more supplies the heat and moisture that power a tropical storm.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;

-- geography / Rivers
insert into public.topics (id, subject_id, slug, name, description, education_stage, sort_order)
