from public.subjects where slug = 'geography'
on conflict (id) do update set name = excluded.name, description = excluded.description;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('e9dbfd9f-a84a-525a-8eb8-daa812c3c799', '5c9bb700-c4b0-52f7-8d50-17b27d29d51d', 'multiple_choice', 'What is the start of a river called?', '[{"id":"A","text":"Source"},{"id":"B","text":"Mouth"},{"id":"C","text":"Confluence"},{"id":"D","text":"Tributary"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('e9dbfd9f-a84a-525a-8eb8-daa812c3c799', 'A', 'The source is where a river begins, often in hills or mountains. The mouth is where it meets the sea.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('713f7eb5-bb85-59e9-8fe4-826ceacf9417', '5c9bb700-c4b0-52f7-8d50-17b27d29d51d', 'multiple_choice', 'What is a smaller river that joins a larger river called?', '[{"id":"A","text":"A tributary"},{"id":"B","text":"A meander"},{"id":"C","text":"A delta"},{"id":"D","text":"An estuary"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('713f7eb5-bb85-59e9-8fe4-826ceacf9417', 'A', 'A tributary flows into a larger river. The point where they meet is called a confluence.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('022c6893-0869-5e91-96dd-f3ed4190217c', '5c9bb700-c4b0-52f7-8d50-17b27d29d51d', 'true_false', 'True or false: deposition happens when a river loses energy.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('022c6893-0869-5e91-96dd-f3ed4190217c', 'A', 'When a river slows down, for example on the inside of a bend or at its mouth, it drops the material it was carrying.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('d84f115b-500b-53a8-ad78-06627c3f7372', '5c9bb700-c4b0-52f7-8d50-17b27d29d51d', 'multiple_choice', 'Which erosion process happens when rocks carried by the river wear away the bed and banks?', '[{"id":"A","text":"Abrasion"},{"id":"B","text":"Attrition"},{"id":"C","text":"Hydraulic action"},{"id":"D","text":"Solution"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('d84f115b-500b-53a8-ad78-06627c3f7372', 'A', 'Abrasion is rocks scraping the bed and banks. Attrition is rocks hitting each other and becoming smaller and rounder.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('f926e959-3b8b-5812-b3b5-3a62aa9e948f', '5c9bb700-c4b0-52f7-8d50-17b27d29d51d', 'multiple_choice', 'How does a waterfall form?', '[{"id":"A","text":"A band of hard rock lies over softer rock, which erodes faster and undercuts the hard rock"},{"id":"B","text":"A river flows uphill"},{"id":"C","text":"Deposition builds up a wall of rock"},{"id":"D","text":"A glacier melts into the river"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('f926e959-3b8b-5812-b3b5-3a62aa9e948f', 'A', 'The soft rock erodes to form an overhang and a plunge pool. The overhang collapses, and the waterfall retreats upstream, forming a gorge.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('43b01b47-efed-59ca-bc08-4f18d24bf500', '5c9bb700-c4b0-52f7-8d50-17b27d29d51d', 'short_answer', 'What is a crescent-shaped lake formed when a meander is cut off from the river called?', null, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, accepted_answers, explanation) values ('43b01b47-efed-59ca-bc08-4f18d24bf500', array['ox-bow lake', 'oxbow lake', 'ox bow lake', 'ox-bow', 'oxbow']::text[], 'Erosion narrows the meander''s neck until the river breaks through. Deposition then seals off the old loop as an ox-bow lake.')
on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('abad3c20-1b83-55c8-ab71-5c7a71d063f5', '5c9bb700-c4b0-52f7-8d50-17b27d29d51d', 'multiple_choice', 'Why does a river''s velocity often increase downstream, even though the gradient gets less steep?', '[{"id":"A","text":"The channel gets wider and deeper, so a smaller share of the water touches the bed and banks, reducing friction"},{"id":"B","text":"The water gets colder"},{"id":"C","text":"Tributaries make the river shallower"},{"id":"D","text":"Gravity is stronger near the sea"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('abad3c20-1b83-55c8-ab71-5c7a71d063f5', 'A', 'A larger, smoother channel is more efficient: less energy is lost to friction, so the water can flow faster.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('58f95332-05d1-555d-af78-4dd71bfcd6bb', '5c9bb700-c4b0-52f7-8d50-17b27d29d51d', 'multiple_choice', 'Which of these is a hard engineering flood defence?', '[{"id":"A","text":"Building embankments"},{"id":"B","text":"Planting trees in the drainage basin"},{"id":"C","text":"Floodplain zoning"},{"id":"D","text":"Restoring the river''s meanders"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('58f95332-05d1-555d-af78-4dd71bfcd6bb', 'A', 'Hard engineering uses built structures such as embankments, dams and flood walls. The other options are soft engineering.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;

-- maths / Ratio and proportion
insert into public.topics (id, subject_id, slug, name, description, education_stage, sort_order)
select '580e0113-1b7a-5d80-bb6b-420674705685', id, 'ratio-proportion', 'Ratio and proportion', 'Sharing in a ratio, simplifying, best buys and direct proportion.', 'gcse', 190
from public.subjects where slug = 'maths'
on conflict (id) do update set name = excluded.name, description = excluded.description;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('96e2b2bb-b5d0-5bbf-a28f-f103ed7de355', '580e0113-1b7a-5d80-bb6b-420674705685', 'multiple_choice', 'What is the ratio 12 : 18 in its simplest form?', '[{"id":"A","text":"2 : 3"},{"id":"B","text":"3 : 2"},{"id":"C","text":"6 : 9"},{"id":"D","text":"4 : 6"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('96e2b2bb-b5d0-5bbf-a28f-f103ed7de355', 'A', 'Divide both parts by their highest common factor, 6: 12 ÷ 6 = 2 and 18 ÷ 6 = 3.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('9a072793-4bb0-566d-b29a-21f3f0b860be', '580e0113-1b7a-5d80-bb6b-420674705685', 'multiple_choice', 'Share £30 in the ratio 1 : 2. How much is the larger share?', '[{"id":"A","text":"£20"},{"id":"B","text":"£15"},{"id":"C","text":"£10"},{"id":"D","text":"£25"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('9a072793-4bb0-566d-b29a-21f3f0b860be', 'A', 'There are 1 + 2 = 3 parts, so one part is £30 ÷ 3 = £10. The larger share is 2 parts = £20.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('7cff9929-2c31-5501-ae82-6c34df91c0b2', '580e0113-1b7a-5d80-bb6b-420674705685', 'true_false', 'True or false: the ratio 3 : 5 is the same as the ratio 5 : 3.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('7cff9929-2c31-5501-ae82-6c34df91c0b2', 'B', 'Order matters in a ratio. 3 : 5 means 3 of the first thing for every 5 of the second; 5 : 3 is the other way round.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('dfddeeb8-4f6a-53f7-940b-5c2df9a5039c', '580e0113-1b7a-5d80-bb6b-420674705685', 'multiple_choice', '4 pens cost £3.20. How much do 7 pens cost at the same price each?', '[{"id":"A","text":"£5.60"},{"id":"B","text":"£5.20"},{"id":"C","text":"£6.40"},{"id":"D","text":"£4.80"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('dfddeeb8-4f6a-53f7-940b-5c2df9a5039c', 'A', 'One pen costs £3.20 ÷ 4 = £0.80, so 7 pens cost 7 × £0.80 = £5.60. This is the unitary method.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('1eff7ba0-21d2-553c-a26b-144b63853e2c', '580e0113-1b7a-5d80-bb6b-420674705685', 'multiple_choice', 'Which is the better buy: 500 g of rice for £1.20 or 1 kg for £2.20?', '[{"id":"A","text":"1 kg for £2.20"},{"id":"B","text":"500 g for £1.20"},{"id":"C","text":"They are the same value"},{"id":"D","text":"You can''t tell without more information"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('1eff7ba0-21d2-553c-a26b-144b63853e2c', 'A', 'Compare the same amount: 1 kg of the smaller bag would cost 2 × £1.20 = £2.40, which is more than £2.20.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('58333c3c-ae75-5f1e-9874-2801bd4574cb', '580e0113-1b7a-5d80-bb6b-420674705685', 'short_answer', 'A recipe for 4 people uses 300 g of flour. How many grams are needed for 6 people? Give the number only.', null, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, accepted_answers, explanation) values ('58333c3c-ae75-5f1e-9874-2801bd4574cb', array['450', '450g', '450 g', '450 grams']::text[], '300 g ÷ 4 = 75 g per person, and 75 g × 6 = 450 g.')
on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('e81d39b3-2a45-5e00-8f25-f386f2c77c2c', '580e0113-1b7a-5d80-bb6b-420674705685', 'multiple_choice', 'y is directly proportional to x. When x = 4, y = 10. What is y when x = 10?', '[{"id":"A","text":"25"},{"id":"B","text":"16"},{"id":"C","text":"40"},{"id":"D","text":"2.5"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('e81d39b3-2a45-5e00-8f25-f386f2c77c2c', 'A', 'y = kx, so k = 10 ÷ 4 = 2.5. When x = 10, y = 2.5 × 10 = 25.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('cc0e35fe-522d-5902-8359-7a64ea4a88ce', '580e0113-1b7a-5d80-bb6b-420674705685', 'multiple_choice', 'The ratio of boys to girls in a club is 3 : 4. There are 12 more girls than boys. How many children are in the club?', '[{"id":"A","text":"84"},{"id":"B","text":"48"},{"id":"C","text":"36"},{"id":"D","text":"28"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('cc0e35fe-522d-5902-8359-7a64ea4a88ce', 'A', 'The difference is 4 − 3 = 1 part, so 1 part = 12. There are 3 + 4 = 7 parts, so 7 × 12 = 84 children.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;

-- maths / Angles and polygons
insert into public.topics (id, subject_id, slug, name, description, education_stage, sort_order)
select '8f7d2efc-b4dd-5400-a2ec-10de4dc60d0e', id, 'angles-polygons', 'Angles and polygons', 'Angle facts, parallel lines and the angles of polygons.', 'gcse', 200
from public.subjects where slug = 'maths'
on conflict (id) do update set name = excluded.name, description = excluded.description;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('50b4e087-b20d-55fd-bef4-c3c7e40f88b7', '8f7d2efc-b4dd-5400-a2ec-10de4dc60d0e', 'multiple_choice', 'What do the angles on a straight line add up to?', '[{"id":"A","text":"180°"},{"id":"B","text":"90°"},{"id":"C","text":"360°"},{"id":"D","text":"270°"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('50b4e087-b20d-55fd-bef4-c3c7e40f88b7', 'A', 'Angles on a straight line add up to 180°. Angles around a point add up to 360°.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('be1c435a-e490-58ad-8d44-ed3bb08ddcad', '8f7d2efc-b4dd-5400-a2ec-10de4dc60d0e', 'multiple_choice', 'Two angles in a triangle are 50° and 60°. What is the third angle?', '[{"id":"A","text":"70°"},{"id":"B","text":"80°"},{"id":"C","text":"90°"},{"id":"D","text":"250°"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('be1c435a-e490-58ad-8d44-ed3bb08ddcad', 'A', 'Angles in a triangle add up to 180°, so the third angle is 180° − 50° − 60° = 70°.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('99d8738f-de0b-587d-8413-5323877febf5', '8f7d2efc-b4dd-5400-a2ec-10de4dc60d0e', 'true_false', 'True or false: vertically opposite angles are equal.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('99d8738f-de0b-587d-8413-5323877febf5', 'A', 'Where two straight lines cross, the angles opposite each other are equal.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('27bbdc04-8b12-5736-9de9-84170b72cedb', '8f7d2efc-b4dd-5400-a2ec-10de4dc60d0e', 'multiple_choice', 'What is the sum of the interior angles of a pentagon?', '[{"id":"A","text":"540°"},{"id":"B","text":"360°"},{"id":"C","text":"720°"},{"id":"D","text":"900°"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('27bbdc04-8b12-5736-9de9-84170b72cedb', 'A', 'Use (n − 2) × 180°. For a pentagon, n = 5, so (5 − 2) × 180° = 540°.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('8360a70d-f839-5988-837b-098fe5433cde', '8f7d2efc-b4dd-5400-a2ec-10de4dc60d0e', 'multiple_choice', 'A line crosses two parallel lines. What can you say about alternate angles?', '[{"id":"A","text":"They are equal"},{"id":"B","text":"They add up to 180°"},{"id":"C","text":"They add up to 90°"},{"id":"D","text":"They add up to 360°"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('8360a70d-f839-5988-837b-098fe5433cde', 'A', 'Alternate angles (a Z shape) are equal. Co-interior angles (a C or U shape) add up to 180°.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('2239faa3-758e-567e-816d-3875e8412e71', '8f7d2efc-b4dd-5400-a2ec-10de4dc60d0e', 'short_answer', 'What is the size of each exterior angle of a regular hexagon, in degrees? Give the number only.', null, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, accepted_answers, explanation) values ('2239faa3-758e-567e-816d-3875e8412e71', array['60', '60°', '60 degrees']::text[], 'Exterior angles of any polygon add up to 360°. A regular hexagon has 6 equal exterior angles: 360° ÷ 6 = 60°.')
on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('8791025a-471c-5327-b7ff-3200adbe56f8', '8f7d2efc-b4dd-5400-a2ec-10de4dc60d0e', 'multiple_choice', 'Each interior angle of a regular polygon is 150°. How many sides does it have?', '[{"id":"A","text":"12"},{"id":"B","text":"10"},{"id":"C","text":"15"},{"id":"D","text":"8"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('8791025a-471c-5327-b7ff-3200adbe56f8', 'A', 'Each exterior angle is 180° − 150° = 30°. The number of sides is 360° ÷ 30° = 12.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('2db35a12-90a6-53a8-8810-dd291bba468c', '8f7d2efc-b4dd-5400-a2ec-10de4dc60d0e', 'multiple_choice', 'An isosceles triangle has one angle of 40° between its two equal sides. What size is each of the other two angles?', '[{"id":"A","text":"70°"},{"id":"B","text":"40°"},{"id":"C","text":"100°"},{"id":"D","text":"50°"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('2db35a12-90a6-53a8-8810-dd291bba468c', 'A', 'The other two angles are equal and share 180° − 40° = 140°, so each is 70°.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;

-- maths / Pythagoras and trigonometry
insert into public.topics (id, subject_id, slug, name, description, education_stage, sort_order)
select '3945f5e8-55e3-5af9-bb0b-1e2d5e0cab28', id, 'pythagoras-trigonometry', 'Pythagoras and trigonometry', 'Right-angled triangles: Pythagoras'' theorem, SOH CAH TOA and exact values.', 'gcse', 210
from public.subjects where slug = 'maths'
on conflict (id) do update set name = excluded.name, description = excluded.description;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('049447b9-bfef-5133-b686-51cdf2b39881', '3945f5e8-55e3-5af9-bb0b-1e2d5e0cab28', 'multiple_choice', 'A right-angled triangle has shorter sides of 3 cm and 4 cm. How long is the hypotenuse?', '[{"id":"A","text":"5 cm"},{"id":"B","text":"7 cm"},{"id":"C","text":"25 cm"},{"id":"D","text":"12 cm"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('049447b9-bfef-5133-b686-51cdf2b39881', 'A', 'By Pythagoras, c² = 3² + 4² = 9 + 16 = 25, so c = √25 = 5 cm.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('d87eb853-51d9-5d75-94f8-1f7e3b99fb5e', '3945f5e8-55e3-5af9-bb0b-1e2d5e0cab28', 'multiple_choice', 'Which side of a right-angled triangle is the hypotenuse?', '[{"id":"A","text":"The longest side, opposite the right angle"},{"id":"B","text":"The shortest side"},{"id":"C","text":"The side next to the angle you are using"},{"id":"D","text":"Any side touching the right angle"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('d87eb853-51d9-5d75-94f8-1f7e3b99fb5e', 'A', 'The hypotenuse is always opposite the right angle, and it is always the longest side.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('2b5d6ba7-0e9e-5402-82d3-54394b0e53a5', '3945f5e8-55e3-5af9-bb0b-1e2d5e0cab28', 'true_false', 'True or false: Pythagoras'' theorem works for every triangle, not only right-angled ones.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('2b5d6ba7-0e9e-5402-82d3-54394b0e53a5', 'B', 'a² + b² = c² only holds for right-angled triangles. Other triangles need the sine or cosine rules.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('6251538d-e422-58ef-9309-830b5d04e4db', '3945f5e8-55e3-5af9-bb0b-1e2d5e0cab28', 'multiple_choice', 'In a right-angled triangle, which ratio is sin x?', '[{"id":"A","text":"Opposite ÷ hypotenuse"},{"id":"B","text":"Adjacent ÷ hypotenuse"},{"id":"C","text":"Opposite ÷ adjacent"},{"id":"D","text":"Hypotenuse ÷ opposite"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('6251538d-e422-58ef-9309-830b5d04e4db', 'A', 'SOH CAH TOA: sin = opposite ÷ hypotenuse, cos = adjacent ÷ hypotenuse, tan = opposite ÷ adjacent.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('8af2c556-613c-5fa7-9831-dbe07483b459', '3945f5e8-55e3-5af9-bb0b-1e2d5e0cab28', 'multiple_choice', 'The hypotenuse of a right-angled triangle is 13 cm and one shorter side is 5 cm. How long is the other side?', '[{"id":"A","text":"12 cm"},{"id":"B","text":"8 cm"},{"id":"C","text":"14 cm"},{"id":"D","text":"18 cm"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('8af2c556-613c-5fa7-9831-dbe07483b459', 'A', 'For a shorter side, subtract: b² = 13² − 5² = 169 − 25 = 144, so b = 12 cm.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('71aeae2f-81a9-5079-9dd7-0cb5c6e9f316', '3945f5e8-55e3-5af9-bb0b-1e2d5e0cab28', 'short_answer', 'What is the exact value of tan 45°?', null, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, accepted_answers, explanation) values ('71aeae2f-81a9-5079-9dd7-0cb5c6e9f316', array['1']::text[], 'In a right-angled isosceles triangle the opposite and adjacent sides are equal, so tan 45° = 1.')
on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('fc070c5f-b478-5297-9b4e-d5838c96cc5b', '3945f5e8-55e3-5af9-bb0b-1e2d5e0cab28', 'multiple_choice', 'A ladder 10 m long leans against a wall and makes an angle of 60° with the ground. How far is the foot of the ladder from the wall?', '[{"id":"A","text":"5 m"},{"id":"B","text":"8.66 m"},{"id":"C","text":"10 m"},{"id":"D","text":"17.3 m"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('fc070c5f-b478-5297-9b4e-d5838c96cc5b', 'A', 'The distance is adjacent to the 60° angle and the ladder is the hypotenuse: 10 × cos 60° = 10 × 0.5 = 5 m.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('63247d4a-b593-5334-8dad-30098a9ae73b', '3945f5e8-55e3-5af9-bb0b-1e2d5e0cab28', 'multiple_choice', 'What is the exact value of sin 30°?', '[{"id":"A","text":"1/2"},{"id":"B","text":"√3/2"},{"id":"C","text":"√2/2"},{"id":"D","text":"1"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('63247d4a-b593-5334-8dad-30098a9ae73b', 'A', 'sin 30° = 1/2, cos 30° = √3/2, and sin 45° = cos 45° = √2/2. These exact values come up in non-calculator questions.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;

-- maths / Probability
insert into public.topics (id, subject_id, slug, name, description, education_stage, sort_order)
select 'b1ec694f-9512-5e55-ab85-d0facee4e554', id, 'probability', 'Probability', 'Probability scales, outcomes, relative frequency and combined events.', 'gcse', 220
from public.subjects where slug = 'maths'
on conflict (id) do update set name = excluded.name, description = excluded.description;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('343723ab-d8ff-56ab-9132-641a0c748285', 'b1ec694f-9512-5e55-ab85-d0facee4e554', 'multiple_choice', 'A fair six-sided dice is rolled. What is the probability of rolling a 4?', '[{"id":"A","text":"1/6"},{"id":"B","text":"1/4"},{"id":"C","text":"4/6"},{"id":"D","text":"1/2"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('343723ab-d8ff-56ab-9132-641a0c748285', 'A', 'There are 6 equally likely outcomes and only one of them is a 4.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('ead555f8-eb58-5ace-b5d2-ad1ea719a6bb', 'b1ec694f-9512-5e55-ab85-d0facee4e554', 'multiple_choice', 'The probability that it rains tomorrow is 0.3. What is the probability that it doesn''t rain?', '[{"id":"A","text":"0.7"},{"id":"B","text":"0.3"},{"id":"C","text":"0.6"},{"id":"D","text":"1.3"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('ead555f8-eb58-5ace-b5d2-ad1ea719a6bb', 'A', 'An event either happens or it doesn''t, so the two probabilities add up to 1: 1 − 0.3 = 0.7.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('9bb79236-8507-5452-b0e8-4f13ac216630', 'b1ec694f-9512-5e55-ab85-d0facee4e554', 'true_false', 'True or false: a probability can be greater than 1.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('9bb79236-8507-5452-b0e8-4f13ac216630', 'B', 'Probabilities go from 0 (impossible) to 1 (certain). Nothing can be more likely than certain.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('ec7c87db-4552-570e-9aa3-65bb9c51b257', 'b1ec694f-9512-5e55-ab85-d0facee4e554', 'multiple_choice', 'A bag has 3 red, 5 blue and 2 green counters. One is taken at random. What is the probability it is blue?', '[{"id":"A","text":"1/2"},{"id":"B","text":"5/8"},{"id":"C","text":"1/5"},{"id":"D","text":"3/10"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('ec7c87db-4552-570e-9aa3-65bb9c51b257', 'A', 'There are 3 + 5 + 2 = 10 counters and 5 are blue, so the probability is 5/10 = 1/2.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('37fda2cc-686d-5373-9727-cbd11e0e5cdc', 'b1ec694f-9512-5e55-ab85-d0facee4e554', 'multiple_choice', 'A drawing pin lands point up 36 times in 120 throws. What is the relative frequency of landing point up?', '[{"id":"A","text":"0.3"},{"id":"B","text":"0.36"},{"id":"C","text":"0.12"},{"id":"D","text":"0.6"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('37fda2cc-686d-5373-9727-cbd11e0e5cdc', 'A', 'Relative frequency = number of times it happened ÷ number of trials = 36 ÷ 120 = 0.3.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('018c844a-6899-565c-9396-2f625b5fb2cd', 'b1ec694f-9512-5e55-ab85-d0facee4e554', 'short_answer', 'A coin is flipped twice. What is the probability of getting two heads? Give your answer as a fraction.', null, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, accepted_answers, explanation) values ('018c844a-6899-565c-9396-2f625b5fb2cd', array['1/4', '0.25']::text[], 'The outcomes HH, HT, TH and TT are equally likely, and only one is HH. Or multiply: 1/2 × 1/2 = 1/4.')
on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('826fdb8a-f49a-5376-b126-9da347abb4a5', 'b1ec694f-9512-5e55-ab85-d0facee4e554', 'multiple_choice', 'A bag has 4 red and 6 blue balls. Two are taken out without replacement. What is the probability both are red?', '[{"id":"A","text":"2/15"},{"id":"B","text":"4/25"},{"id":"C","text":"4/15"},{"id":"D","text":"1/5"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('826fdb8a-f49a-5376-b126-9da347abb4a5', 'A', 'P(red then red) = 4/10 × 3/9 = 12/90 = 2/15. The second fraction changes because the first ball isn''t put back.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('66fff798-f395-5334-829b-aa6edf6c2182', 'b1ec694f-9512-5e55-ab85-d0facee4e554', 'multiple_choice', 'Two fair dice are rolled. What is the probability that the total is 7?', '[{"id":"A","text":"1/6"},{"id":"B","text":"1/12"},{"id":"C","text":"7/36"},{"id":"D","text":"1/11"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('66fff798-f395-5334-829b-aa6edf6c2182', 'A', 'There are 36 equally likely outcomes, and 6 give a total of 7: (1,6), (2,5), (3,4), (4,3), (5,2) and (6,1). 6/36 = 1/6.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;

