insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('2198804b-17cb-5eb7-802b-1a76db5563ff', '4de60c78-119c-53d0-918b-f4857b014c40', 'multiple_choice', 'What is the main purpose of a persuasive article?', '[{"id":"A","text":"To make the reader agree with a point of view or take action"},{"id":"B","text":"To tell a story with characters"},{"id":"C","text":"To give instructions in order"},{"id":"D","text":"To describe a place in detail"}]'::jsonb, 'foundation', 'question_bank', true)
