insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('eb98ea2c-943a-5c13-a824-64e694a23151', '4de60c78-119c-53d0-918b-f4857b014c40', 'true_false', 'True or false: using "we" and "us" can help a writer make the reader feel included.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
