insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('f2079a82-488d-56c6-9fa7-7b60dc836d67', '4de60c78-119c-53d0-918b-f4857b014c40', 'multiple_choice', '"It''s cheap, it''s quick and it''s easy." Which technique does this use?', '[{"id":"A","text":"A list of three (triplet)"},{"id":"B","text":"Hyperbole"},{"id":"C","text":"Counter-argument"},{"id":"D","text":"Alliteration"}]'::jsonb, 'standard', 'question_bank', true)
