insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('da1e3999-858e-5d9d-9757-2fb8b193f2a6', '4de60c78-119c-53d0-918b-f4857b014c40', 'multiple_choice', 'Why might a writer include a counter-argument and then reject it?', '[{"id":"A","text":"To show they have considered other views, which makes their own argument seem stronger"},{"id":"B","text":"To confuse the reader"},{"id":"C","text":"To make the article longer"},{"id":"D","text":"Because they have changed their mind"}]'::jsonb, 'standard', 'question_bank', true)
