on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('79b3ff37-8f9b-5090-a1f8-0a973cf744f0', '4de60c78-119c-53d0-918b-f4857b014c40', 'short_answer', 'What is the term for a short personal story used to support an argument?', null, 'standard', 'question_bank', true)
