insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('bda7df91-4482-57f6-bd09-78e0c6561e0f', '8da4d3f5-4c13-5f74-a8da-9a0d70947245', 'multiple_choice', 'What is a flashback?', '[{"id":"A","text":"A scene that goes back to events from an earlier time"},{"id":"B","text":"A hint about what will happen later"},{"id":"C","text":"A very short sentence"},{"id":"D","text":"The final scene of a story"}]'::jsonb, 'foundation', 'question_bank', true)
