insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('30e570bb-dff2-56ca-b2e2-0bf7a4bcfb70', '8da4d3f5-4c13-5f74-a8da-9a0d70947245', 'multiple_choice', 'A story told using "I" by one of the characters is written in which narrative voice?', '[{"id":"A","text":"First person"},{"id":"B","text":"Second person"},{"id":"C","text":"Third person"},{"id":"D","text":"Omniscient"}]'::jsonb, 'foundation', 'question_bank', true)
