insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('8e480289-44ff-5591-b551-cf0567113019', '8da4d3f5-4c13-5f74-a8da-9a0d70947245', 'true_false', 'True or false: a cliffhanger ends a section with the outcome left uncertain.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
