insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('58e89cf2-37ba-53db-bb2b-bdb16cf5439f', '8da4d3f5-4c13-5f74-a8da-9a0d70947245', 'multiple_choice', 'A text opens by describing a whole city, then focuses on one window, then on one person inside. What structural technique is this?', '[{"id":"A","text":"Narrowing the focus, like a camera zooming in"},{"id":"B","text":"A circular structure"},{"id":"C","text":"A flashback"},{"id":"D","text":"Dialogue"}]'::jsonb, 'standard', 'question_bank', true)
