insert into public.question_answers (question_id, correct_option, explanation) values ('58e89cf2-37ba-53db-bb2b-bdb16cf5439f', 'A', 'Moving from wide to close focus guides the reader''s attention towards what matters, much like a film shot.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('7045d79f-d05b-5de3-99dd-e45cea884426', '8da4d3f5-4c13-5f74-a8da-9a0d70947245', 'multiple_choice', 'What is a circular (cyclical) structure?', '[{"id":"A","text":"The ending returns to an image or idea from the opening"},{"id":"B","text":"The story is told in the present tense"},{"id":"C","text":"Each chapter has a different narrator"},{"id":"D","text":"The story has no ending"}]'::jsonb, 'standard', 'question_bank', true)
