on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('f0555741-db7f-5c82-8ac6-916644091a30', '8da4d3f5-4c13-5f74-a8da-9a0d70947245', 'short_answer', 'What is the term for hints early in a story about what will happen later?', null, 'standard', 'question_bank', true)
