insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('1182f30e-7269-5813-bfe0-ccf6e32d3a8c', '1bc39e62-9dc9-5651-89b1-625ee8bd7613', 'multiple_choice', 'Which verb best shows that a character is angry?', '[{"id":"A","text":"stormed"},{"id":"B","text":"went"},{"id":"C","text":"moved"},{"id":"D","text":"walked"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('1182f30e-7269-5813-bfe0-ccf6e32d3a8c', 'A', '"Stormed" is a precise verb that shows both the action and the emotion, so the writer doesn''t need to say "angrily".')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('76dda17d-e177-5233-bdcb-f7557703397c', '1bc39e62-9dc9-5651-89b1-625ee8bd7613', 'multiple_choice', 'What is a synonym?', '[{"id":"A","text":"A word with the same or a similar meaning to another word"},{"id":"B","text":"A word with the opposite meaning"},{"id":"C","text":"A word that sounds the same but is spelt differently"},{"id":"D","text":"A word made from the first letters of other words"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('76dda17d-e177-5233-bdcb-f7557703397c', 'A', 'Synonyms such as "big" and "enormous" help writers vary vocabulary. Antonyms are opposites.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('c856add9-07b9-535a-af04-67ba9bf2616e', '1bc39e62-9dc9-5651-89b1-625ee8bd7613', 'short_answer', 'What word class is "between" in "The cat hid between the boxes"?', null, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, accepted_answers, explanation) values ('c856add9-07b9-535a-af04-67ba9bf2616e', array['preposition', 'a preposition']::text[], 'Prepositions show position, direction or time, linking a noun to the rest of the sentence.')
on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('76bc6900-8b54-5890-beb7-9bcf9e8f81fb', '1bc39e62-9dc9-5651-89b1-625ee8bd7613', 'multiple_choice', '"The sky bled red." What is the effect of the verb "bled"?', '[{"id":"A","text":"It suggests violence or pain, creating a threatening mood"},{"id":"B","text":"It tells the reader the time of day only"},{"id":"C","text":"It is a fact about the weather"},{"id":"D","text":"It makes the sentence longer"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('76bc6900-8b54-5890-beb7-9bcf9e8f81fb', 'A', 'The connotations of "bled" (injury, danger) turn a sunset into something ominous. Analysing connotations is a key reading skill.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('16ac5542-e1e0-521a-9d29-3a8c847adb51', '1bc39e62-9dc9-5651-89b1-625ee8bd7613', 'multiple_choice', 'What are connotations?', '[{"id":"A","text":"The ideas and feelings a word suggests beyond its literal meaning"},{"id":"B","text":"The dictionary definition of a word"},{"id":"C","text":"Words that rhyme"},{"id":"D","text":"The grammatical class of a word"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('16ac5542-e1e0-521a-9d29-3a8c847adb51', 'A', '"Home" literally means where you live, but it connotes safety and belonging. Writers choose words for these associations.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;

