insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('2fb0de11-d555-599a-ae8b-5a3ec43b28fb', '19e5a632-e716-572c-940c-6331f12907c0', 'multiple_choice', 'Which word correctly completes the sentence: "___ going to the cinema tonight."', '[{"id":"A","text":"They''re"},{"id":"B","text":"Their"},{"id":"C","text":"There"},{"id":"D","text":"Thier"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('2fb0de11-d555-599a-ae8b-5a3ec43b28fb', 'A', '"They''re" is short for "they are". "Their" shows belonging and "there" is about place.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('85a4e2cc-555c-56a6-88bb-54c568ec47e9', '19e5a632-e716-572c-940c-6331f12907c0', 'multiple_choice', 'Which sentence is spelt correctly?', '[{"id":"A","text":"I will see you tomorrow."},{"id":"B","text":"I will see you tommorow."},{"id":"C","text":"I will see you tomorow."},{"id":"D","text":"I will see you tommorrow."}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('85a4e2cc-555c-56a6-88bb-54c568ec47e9', 'A', '"Tomorrow" has one m and two r''s.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('705ecf9a-9e26-5f7b-b05f-5f93bdc0f0da', '19e5a632-e716-572c-940c-6331f12907c0', 'true_false', 'True or false: "its" (without an apostrophe) means "belonging to it".', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('705ecf9a-9e26-5f7b-b05f-5f93bdc0f0da', 'A', '"Its" is possessive, like "his". "It''s" with an apostrophe means "it is" or "it has".')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('ca33119f-d3e6-5ef2-aa59-54f6cd6bff32', '19e5a632-e716-572c-940c-6331f12907c0', 'multiple_choice', 'Which word completes the sentence: "The weather had a big ___ on the match."', '[{"id":"A","text":"effect"},{"id":"B","text":"affect"},{"id":"C","text":"afect"},{"id":"D","text":"efect"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('ca33119f-d3e6-5ef2-aa59-54f6cd6bff32', 'A', '"Effect" is usually a noun (a result). "Affect" is usually a verb (to influence): the weather affected the match.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('3b4e361d-2de2-59bb-a209-d93c17d08983', '19e5a632-e716-572c-940c-6331f12907c0', 'multiple_choice', 'Which is the correct spelling?', '[{"id":"A","text":"necessary"},{"id":"B","text":"neccessary"},{"id":"C","text":"necesary"},{"id":"D","text":"neccesary"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('3b4e361d-2de2-59bb-a209-d93c17d08983', 'A', '"Necessary" has one c and two s''s. One way to remember: one collar, two sleeves.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('3f9721fe-458a-5aa5-9ce2-bbafdc409c49', '19e5a632-e716-572c-940c-6331f12907c0', 'short_answer', 'Complete with "to", "too" or "two": "The soup was ___ hot to eat."', null, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, accepted_answers, explanation) values ('3f9721fe-458a-5aa5-9ce2-bbafdc409c49', array['too']::text[], '"Too" means excessively or also. "Two" is the number and "to" shows direction or comes before a verb.')
on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('1dfe7af6-bc19-5592-ade7-069b17774eb9', '19e5a632-e716-572c-940c-6331f12907c0', 'multiple_choice', 'Which sentence is correct?', '[{"id":"A","text":"You should have checked the map."},{"id":"B","text":"You should of checked the map."},{"id":"C","text":"You should''ve of checked the map."},{"id":"D","text":"You should off checked the map."}]'::jsonb, 'challenge', 'question_bank', true)
