insert into public.question_answers (question_id, correct_option, explanation) values ('1dfe7af6-bc19-5592-ade7-069b17774eb9', 'A', '"Should''ve" sounds like "should of", but the correct form is "should have". The same applies to could have and would have.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('876b1f7a-3ca8-5481-b693-5c0c492669d2', '19e5a632-e716-572c-940c-6331f12907c0', 'multiple_choice', 'Which pair of words are both spelt correctly?', '[{"id":"A","text":"separate, definitely"},{"id":"B","text":"seperate, definately"},{"id":"C","text":"separate, definately"},{"id":"D","text":"seperate, definitely"}]'::jsonb, 'challenge', 'question_bank', true)
