from public.subjects where slug = 'english-literature'
on conflict (id) do update set name = excluded.name, description = excluded.description;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('f8da892c-5865-5c0b-89ae-14607011c50f', '226f9dae-bd8b-50f6-87f9-e6276922a7e1', 'multiple_choice', 'In which Italian city is Romeo and Juliet set?', '[{"id":"A","text":"Verona"},{"id":"B","text":"Venice"},{"id":"C","text":"Rome"},{"id":"D","text":"Florence"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('f8da892c-5865-5c0b-89ae-14607011c50f', 'A', 'The play is set in Verona, where the Montague and Capulet families are feuding.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('f128586f-acbf-59ab-9f39-a3157ffa4630', '226f9dae-bd8b-50f6-87f9-e6276922a7e1', 'multiple_choice', 'Which family does Juliet belong to?', '[{"id":"A","text":"The Capulets"},{"id":"B","text":"The Montagues"},{"id":"C","text":"The Tudors"},{"id":"D","text":"The Macbeths"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('f128586f-acbf-59ab-9f39-a3157ffa4630', 'A', 'Juliet is a Capulet and Romeo is a Montague. Their families'' feud is what makes the love dangerous.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('a0d97bea-ad20-58cb-abaf-0c4c96971c0a', '226f9dae-bd8b-50f6-87f9-e6276922a7e1', 'true_false', 'True or false: the Prologue tells the audience at the start that Romeo and Juliet will die.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('a0d97bea-ad20-58cb-abaf-0c4c96971c0a', 'A', 'The Prologue calls them "star-crossed lovers" and reveals their deaths, so the audience watches knowing the tragic ending.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('b2b926e8-d390-512f-b39e-107a7ad1cc42', '226f9dae-bd8b-50f6-87f9-e6276922a7e1', 'multiple_choice', 'Who secretly marries Romeo and Juliet?', '[{"id":"A","text":"Friar Laurence"},{"id":"B","text":"The Nurse"},{"id":"C","text":"Mercutio"},{"id":"D","text":"Prince Escalus"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('b2b926e8-d390-512f-b39e-107a7ad1cc42', 'A', 'Friar Laurence agrees to marry them, hoping the match will end the feud between the families.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('e72a932e-0a40-598a-ab0d-4511d10af4de', '226f9dae-bd8b-50f6-87f9-e6276922a7e1', 'multiple_choice', 'Why is Romeo banished from Verona?', '[{"id":"A","text":"He kills Tybalt after Tybalt kills Mercutio"},{"id":"B","text":"He marries Juliet in secret"},{"id":"C","text":"He gatecrashes the Capulet party"},{"id":"D","text":"He insults the Prince"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('e72a932e-0a40-598a-ab0d-4511d10af4de', 'A', 'Tybalt kills Mercutio, and Romeo takes revenge by killing Tybalt. The Prince banishes Romeo instead of sentencing him to death.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('3d37d275-18d5-502b-bc02-cd56f90fba78', '226f9dae-bd8b-50f6-87f9-e6276922a7e1', 'short_answer', 'Which character, Romeo''s friend, makes the Queen Mab speech?', null, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, accepted_answers, explanation) values ('3d37d275-18d5-502b-bc02-cd56f90fba78', array['mercutio']::text[], 'Mercutio''s witty, wild Queen Mab speech mocks the idea that dreams mean anything, contrasting with Romeo''s sense of fate.')
on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('81bf9608-dadb-5660-948f-0ee071779459', '226f9dae-bd8b-50f6-87f9-e6276922a7e1', 'multiple_choice', 'Which theme is most strongly shown by the Prologue''s phrase "star-crossed lovers"?', '[{"id":"A","text":"Fate"},{"id":"B","text":"Friendship"},{"id":"C","text":"Wealth"},{"id":"D","text":"Religion"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('81bf9608-dadb-5660-948f-0ee071779459', 'A', '"Star-crossed" suggests the stars (fate) are against them, so the tragedy seems destined from the start.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('d3562812-062c-560d-870b-9e4f60c0c0c6', '226f9dae-bd8b-50f6-87f9-e6276922a7e1', 'multiple_choice', 'Why is it significant that Lord Capulet arranges Juliet''s marriage to Paris?', '[{"id":"A","text":"It reflects the Elizabethan expectation that daughters obey their fathers, and pushes Juliet to a desperate plan"},{"id":"B","text":"It shows Capulet wants to end the feud"},{"id":"C","text":"It proves Paris is Romeo''s cousin"},{"id":"D","text":"It means Juliet is a Montague"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('d3562812-062c-560d-870b-9e4f60c0c0c6', 'A', 'In Shakespeare''s time, fathers had great power over daughters'' marriages. Juliet''s refusal and Capulet''s fury lead to the Friar''s potion plan.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;

