insert into public.question_answers (question_id, correct_option, explanation) values ('06559427-1ad0-52f5-ba6e-db4f841b4540', 'A', 'J.B. Priestley wrote the play. It was first performed in 1945 and is set in 1912.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('b9a9debb-30c4-58b1-bec3-854fc952b270', '28634ab3-d469-5f2c-b78e-ba6126aa77c6', 'multiple_choice', 'What is the name of the young woman whose death the Inspector investigates?', '[{"id":"A","text":"Eva Smith"},{"id":"B","text":"Sheila Birling"},{"id":"C","text":"Edna"},{"id":"D","text":"Gerald Croft"}]'::jsonb, 'foundation', 'question_bank', true)
