insert into public.question_answers (question_id, correct_option, explanation) values ('b9a9debb-30c4-58b1-bec3-854fc952b270', 'A', 'The Inspector says Eva Smith has died, and shows that each member of the family played a part in her life going wrong.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('0551b859-306f-5143-b369-32a326178c21', '28634ab3-d469-5f2c-b78e-ba6126aa77c6', 'true_false', 'True or false: the play is set in 1912 but was written after the Second World War had ended.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('0551b859-306f-5143-b369-32a326178c21', 'A', 'Setting it in 1912 lets Priestley''s 1945 audience see how wrong Mr Birling''s confident predictions were.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('ef49f6ee-4299-5f5e-8f62-7bddab5930df', '28634ab3-d469-5f2c-b78e-ba6126aa77c6', 'multiple_choice', 'Why did Mr Birling sack Eva Smith from his factory?', '[{"id":"A","text":"She was one of the leaders of a strike for higher wages"},{"id":"B","text":"She was rude to Sheila in a shop"},{"id":"C","text":"She stole money"},{"id":"D","text":"She was always late"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('ef49f6ee-4299-5f5e-8f62-7bddab5930df', 'A', 'Birling sacked her for asking for better pay, which shows his capitalist belief that a man should look after himself and his own.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('822fbed5-b4cc-55ab-ad84-d77e6edf1555', '28634ab3-d469-5f2c-b78e-ba6126aa77c6', 'multiple_choice', 'What does Mr Birling confidently predict about the Titanic?', '[{"id":"A","text":"That it is unsinkable"},{"id":"B","text":"That it will sink"},{"id":"C","text":"That he will sail on it"},{"id":"D","text":"That it is too expensive"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('822fbed5-b4cc-55ab-ad84-d77e6edf1555', 'A', 'This is dramatic irony: the audience knows the Titanic sank in 1912, so Birling''s judgement can''t be trusted.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('8e7096d3-1ac7-5274-8613-919c1eb12666', '28634ab3-d469-5f2c-b78e-ba6126aa77c6', 'short_answer', 'Which member of the Birling family is the most willing to accept responsibility and change by the end?', null, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, accepted_answers, explanation) values ('8e7096d3-1ac7-5274-8613-919c1eb12666', array['sheila', 'sheila birling']::text[], 'Sheila, along with Eric, accepts her part in Eva''s death. Priestley uses the younger generation to show hope for change.')
on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('d8a0def9-71e6-5b7f-aa64-7557b870b2dc', '28634ab3-d469-5f2c-b78e-ba6126aa77c6', 'multiple_choice', 'What is the Inspector''s main message in his final speech?', '[{"id":"A","text":"We are all responsible for each other"},{"id":"B","text":"Hard work always leads to success"},{"id":"C","text":"The upper class should be in charge"},{"id":"D","text":"Crime should be punished harshly"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('d8a0def9-71e6-5b7f-aa64-7557b870b2dc', 'A', 'The Inspector warns that if people don''t learn they are "members of one body", they will learn in "fire and blood and anguish", a reference to the wars to come.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('0d536130-f5fa-55bb-a409-37cc423908a9', '28634ab3-d469-5f2c-b78e-ba6126aa77c6', 'multiple_choice', 'Why might Priestley have made the Inspector''s identity uncertain at the end?', '[{"id":"A","text":"So the focus stays on the family''s choices and the message of responsibility rather than on whether he was real"},{"id":"B","text":"Because Priestley forgot to explain it"},{"id":"C","text":"To show the police are untrustworthy"},{"id":"D","text":"To make Gerald the hero"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('0d536130-f5fa-55bb-a409-37cc423908a9', 'A', 'Whether or not he was a real inspector, the family did those things. The phone call at the end tests whether they have learned anything.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;

