insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('934a13f0-a101-5e37-badb-0cf7c3a72d1e', 'a5a7d2ad-7c74-58d3-a51e-f037ec7252a2', 'multiple_choice', 'Which character is a lawyer and Jekyll''s friend, and investigates Hyde?', '[{"id":"A","text":"Mr Utterson"},{"id":"B","text":"Dr Lanyon"},{"id":"C","text":"Poole"},{"id":"D","text":"Sir Danvers Carew"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('934a13f0-a101-5e37-badb-0cf7c3a72d1e', 'A', 'Utterson is a respectable lawyer. Much of the story follows his attempts to find out who Hyde is.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('78ff19ca-ca1a-5ba0-92ed-c717f47e6c42', 'a5a7d2ad-7c74-58d3-a51e-f037ec7252a2', 'true_false', 'True or false: Jekyll and Hyde turn out to be the same person.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('78ff19ca-ca1a-5ba0-92ed-c717f47e6c42', 'A', 'Jekyll''s potion transforms him into Hyde, letting him act on desires he hides as a respectable gentleman.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('3f54c6fc-3496-58a0-9193-dbf8b4268ff9', 'a5a7d2ad-7c74-58d3-a51e-f037ec7252a2', 'multiple_choice', 'Which violent act by Hyde shocks London in the novella?', '[{"id":"A","text":"The murder of Sir Danvers Carew"},{"id":"B","text":"Burning down Jekyll''s house"},{"id":"C","text":"Robbing a bank"},{"id":"D","text":"Poisoning Utterson"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('3f54c6fc-3496-58a0-9193-dbf8b4268ff9', 'A', 'Hyde beats Sir Danvers Carew, an MP, to death with a cane. A maid witnesses it from a window.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('06f3bb64-fa2e-5d39-af84-6983287d57bc', 'a5a7d2ad-7c74-58d3-a51e-f037ec7252a2', 'multiple_choice', 'Which theme is central to the novella?', '[{"id":"A","text":"The duality of human nature: good and evil within one person"},{"id":"B","text":"Romantic love"},{"id":"C","text":"Life at sea"},{"id":"D","text":"War between nations"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('06f3bb64-fa2e-5d39-af84-6983287d57bc', 'A', 'Jekyll believes that "man is not truly one, but truly two". The novel explores the hidden, darker side of respectable people.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('90d084e0-6116-52f9-beef-20f62c4fd0d8', 'a5a7d2ad-7c74-58d3-a51e-f037ec7252a2', 'short_answer', 'Which doctor dies of shock after seeing Hyde transform into Jekyll?', null, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, accepted_answers, explanation) values ('90d084e0-6116-52f9-beef-20f62c4fd0d8', array['lanyon', 'dr lanyon', 'doctor lanyon', 'hastie lanyon']::text[], 'Dr Lanyon, a rational scientist, cannot cope with what he witnesses. His letter reveals the truth to Utterson.')
on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('fc43e31e-033d-5112-9380-9d8ffc958153', 'a5a7d2ad-7c74-58d3-a51e-f037ec7252a2', 'multiple_choice', 'How does the novella reflect Victorian concerns about reputation?', '[{"id":"A","text":"Characters avoid scandal and gossip, so Jekyll hides his wrongdoing behind a respectable public face"},{"id":"B","text":"Everyone in the story openly discusses their secrets"},{"id":"C","text":"Characters care only about money"},{"id":"D","text":"The story celebrates rule-breaking"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('fc43e31e-033d-5112-9380-9d8ffc958153', 'A', 'Utterson and Enfield avoid asking questions to protect reputations. Respectability matters more than truth, which lets Hyde thrive.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('75117330-b569-5506-af19-487dffcb813f', 'a5a7d2ad-7c74-58d3-a51e-f037ec7252a2', 'multiple_choice', 'Why is Hyde often described as small, and how is he linked to ideas of the time?', '[{"id":"A","text":"He represents a less developed, primitive side of Jekyll, echoing fears linked to theories of evolution"},{"id":"B","text":"Because he is a child"},{"id":"C","text":"Because Stevenson disliked tall people"},{"id":"D","text":"To show he is poor"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('75117330-b569-5506-af19-487dffcb813f', 'A', 'Hyde is described in animal-like, "troglodytic" terms. Victorian readers, aware of Darwin''s ideas, feared humans could regress.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;

