insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('df69ab75-73dc-5c56-b614-b535a87e9e38', 'ee179c51-85ad-5cbd-a4f0-9e03f2f5b384', 'multiple_choice', 'What is a dramatic monologue?', '[{"id":"A","text":"A poem spoken by a single character, often revealing more about them than they intend"},{"id":"B","text":"A poem with two speakers arguing"},{"id":"C","text":"A play performed by one actor"},{"id":"D","text":"A poem that tells a story with a chorus"}]'::jsonb, 'standard', 'question_bank', true)
