insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('dd0ae09e-45a1-53c5-a782-b5429048e7b2', 'ee179c51-85ad-5cbd-a4f0-9e03f2f5b384', 'short_answer', 'What is the name for a pause in the middle of a line of poetry, often marked by punctuation?', null, 'standard', 'question_bank', true)
