insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('11fd5f5d-a100-5077-8194-56d3f69367c4', '4da5b18e-c26a-5f8d-800c-cda11990a0ce', 'multiple_choice', 'Which chamber of the heart pumps blood out to the whole body?', '[{"id":"A","text":"The left ventricle"},{"id":"B","text":"The right ventricle"},{"id":"C","text":"The left atrium"},{"id":"D","text":"The right atrium"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('11fd5f5d-a100-5077-8194-56d3f69367c4', 'A', 'The left ventricle has the thickest muscle wall because it pumps blood around the whole body. The right ventricle pumps blood to the lungs.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('bf6e4c55-ec71-50bc-ac35-54e428d3be06', '4da5b18e-c26a-5f8d-800c-cda11990a0ce', 'short_answer', 'Which organ produces bile?', null, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, accepted_answers, explanation) values ('bf6e4c55-ec71-50bc-ac35-54e428d3be06', array['liver', 'the liver']::text[], 'Bile is made in the liver and stored in the gall bladder. It neutralises stomach acid and emulsifies fats.')
on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('4d282f43-579c-5f35-a3e4-0e2147ee6531', '4da5b18e-c26a-5f8d-800c-cda11990a0ce', 'multiple_choice', 'Why is the human circulatory system described as a double circulatory system?', '[{"id":"A","text":"Blood passes through the heart twice in each full circuit of the body"},{"id":"B","text":"There are two hearts"},{"id":"C","text":"Blood flows in two directions in each vessel"},{"id":"D","text":"There are two types of blood"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('4d282f43-579c-5f35-a3e4-0e2147ee6531', 'A', 'One circuit takes blood from the heart to the lungs and back; the other takes it from the heart to the body and back.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('665f0585-684f-5947-9b70-4f7ac3efb42d', '4da5b18e-c26a-5f8d-800c-cda11990a0ce', 'multiple_choice', 'Which feature of capillaries makes them well suited to exchanging substances with cells?', '[{"id":"A","text":"Walls only one cell thick"},{"id":"B","text":"Thick muscular walls"},{"id":"C","text":"Valves along their length"},{"id":"D","text":"A wide lumen"}]'::jsonb, 'challenge', 'question_bank', true)
