insert into public.question_answers (question_id, correct_option, explanation) values ('665f0585-684f-5947-9b70-4f7ac3efb42d', 'A', 'Very thin walls give a short diffusion distance. Thick muscular walls belong to arteries; valves are found in veins.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;

-- biology / Bioenergetics
insert into public.topics (id, subject_id, slug, name, description, education_stage, sort_order)
