from public.subjects where slug = 'biology'
on conflict (id) do update set name = excluded.name, description = excluded.description;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('aaffc753-7a6e-55e0-bf48-d71b6ddc3384', '76f1fb67-3ca5-5234-945d-11d29a68957d', 'multiple_choice', 'What are the products of photosynthesis?', '[{"id":"A","text":"Glucose and oxygen"},{"id":"B","text":"Carbon dioxide and water"},{"id":"C","text":"Glucose and carbon dioxide"},{"id":"D","text":"Oxygen and water"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('aaffc753-7a6e-55e0-bf48-d71b6ddc3384', 'A', 'Carbon dioxide + water → glucose + oxygen, using light energy absorbed by chlorophyll.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('c3936f00-d6d1-53e6-803d-d988b4710113', '76f1fb67-3ca5-5234-945d-11d29a68957d', 'multiple_choice', 'Where in a plant cell does photosynthesis take place?', '[{"id":"A","text":"Chloroplasts"},{"id":"B","text":"Mitochondria"},{"id":"C","text":"The nucleus"},{"id":"D","text":"The cell wall"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('c3936f00-d6d1-53e6-803d-d988b4710113', 'A', 'Chloroplasts contain chlorophyll, which absorbs light. Mitochondria are where aerobic respiration happens.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('7dd7d437-aa77-58ee-abeb-656edde8c4ca', '76f1fb67-3ca5-5234-945d-11d29a68957d', 'true_false', 'True or false: photosynthesis is an endothermic reaction.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('7dd7d437-aa77-58ee-abeb-656edde8c4ca', 'A', 'Photosynthesis takes in energy (as light) from the surroundings, so it is endothermic. Respiration is exothermic.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('7fa9c0e0-0017-5c56-ba23-1399763132f4', '76f1fb67-3ca5-5234-945d-11d29a68957d', 'multiple_choice', 'What is produced by anaerobic respiration in human muscles?', '[{"id":"A","text":"Lactic acid"},{"id":"B","text":"Ethanol and carbon dioxide"},{"id":"C","text":"Oxygen"},{"id":"D","text":"Glucose"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('7fa9c0e0-0017-5c56-ba23-1399763132f4', 'A', 'Without enough oxygen, muscles convert glucose to lactic acid. Yeast makes ethanol and carbon dioxide instead.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('fc2c4e14-f753-5246-a398-641eb4bbe4c4', '76f1fb67-3ca5-5234-945d-11d29a68957d', 'multiple_choice', 'Which of these is NOT a limiting factor for photosynthesis?', '[{"id":"A","text":"Oxygen concentration"},{"id":"B","text":"Light intensity"},{"id":"C","text":"Carbon dioxide concentration"},{"id":"D","text":"Temperature"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('fc2c4e14-f753-5246-a398-641eb4bbe4c4', 'A', 'Light intensity, carbon dioxide concentration, temperature and the amount of chlorophyll can limit the rate. Oxygen is a product.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('b37d1e60-c9fc-5997-9350-18ed77f38b95', '76f1fb67-3ca5-5234-945d-11d29a68957d', 'short_answer', 'What is the extra oxygen needed after exercise to break down lactic acid called?', null, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, accepted_answers, explanation) values ('b37d1e60-c9fc-5997-9350-18ed77f38b95', array['oxygen debt', 'the oxygen debt']::text[], 'During hard exercise muscles respire anaerobically. Afterwards, the oxygen debt is repaid by breathing deeply to remove lactic acid.')
on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('30bc7fdc-8a3e-53c6-b765-097783a82903', '76f1fb67-3ca5-5234-945d-11d29a68957d', 'multiple_choice', 'Moving a lamp twice as far from a plant reduces the light intensity to what fraction?', '[{"id":"A","text":"One quarter"},{"id":"B","text":"One half"},{"id":"C","text":"Two thirds"},{"id":"D","text":"It doesn''t change"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('30bc7fdc-8a3e-53c6-b765-097783a82903', 'A', 'Light intensity follows an inverse square law: intensity ∝ 1/distance². Doubling the distance gives 1/2² = 1/4.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('b9b2b068-8371-5ed9-a78c-045c32a68179', '76f1fb67-3ca5-5234-945d-11d29a68957d', 'multiple_choice', 'Why does aerobic respiration release more energy per glucose molecule than anaerobic respiration?', '[{"id":"A","text":"Glucose is completely oxidised to carbon dioxide and water"},{"id":"B","text":"It happens faster"},{"id":"C","text":"It uses lactic acid as a fuel"},{"id":"D","text":"It happens in the cytoplasm"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('b9b2b068-8371-5ed9-a78c-045c32a68179', 'A', 'In anaerobic respiration glucose is only partly broken down, so much of its energy stays locked in lactic acid.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;

