insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('190cfb60-26e6-5b22-b21b-0a4ba2de03d6', '7eca6fef-c4a6-51b7-8711-6360a53fa84e', 'multiple_choice', 'What is homeostasis?', '[{"id":"A","text":"Keeping internal conditions stable"},{"id":"B","text":"The growth of new cells"},{"id":"C","text":"The movement of water into cells"},{"id":"D","text":"The way plants make food"}]'::jsonb, 'foundation', 'question_bank', true)
