insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('856c4576-7412-5197-bbf0-6bfa77c2a306', '7eca6fef-c4a6-51b7-8711-6360a53fa84e', 'multiple_choice', 'Which gland releases insulin?', '[{"id":"A","text":"The pancreas"},{"id":"B","text":"The thyroid"},{"id":"C","text":"The pituitary gland"},{"id":"D","text":"The adrenal gland"}]'::jsonb, 'foundation', 'question_bank', true)
