insert into public.question_answers (question_id, correct_option, explanation) values ('856c4576-7412-5197-bbf0-6bfa77c2a306', 'A', 'The pancreas releases insulin when blood glucose is too high, and glucagon when it is too low.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('09bde80b-8737-5962-b4bc-640ddab2f6c2', '7eca6fef-c4a6-51b7-8711-6360a53fa84e', 'true_false', 'True or false: reflex actions are automatic and don''t involve the conscious part of the brain.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
