insert into public.question_answers (question_id, correct_option, explanation) values ('09bde80b-8737-5962-b4bc-640ddab2f6c2', 'A', 'Reflexes are rapid and automatic, which helps protect the body from harm, for example pulling a hand away from heat.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('1cc7d892-947a-5794-b3f4-a5c9dda91e9c', '7eca6fef-c4a6-51b7-8711-6360a53fa84e', 'multiple_choice', 'What is the correct order of a reflex arc?', '[{"id":"A","text":"Receptor, sensory neurone, relay neurone, motor neurone, effector"},{"id":"B","text":"Effector, motor neurone, relay neurone, sensory neurone, receptor"},{"id":"C","text":"Receptor, motor neurone, relay neurone, sensory neurone, effector"},{"id":"D","text":"Sensory neurone, receptor, effector, motor neurone"}]'::jsonb, 'standard', 'question_bank', true)
