insert into public.question_answers (question_id, correct_option, explanation) values ('1cc7d892-947a-5794-b3f4-a5c9dda91e9c', 'A', 'The stimulus is detected by a receptor, passed along sensory, relay and motor neurones, and the effector responds.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('dc865c5f-135b-5465-bab9-4588b29d00f6', '7eca6fef-c4a6-51b7-8711-6360a53fa84e', 'multiple_choice', 'What happens when blood glucose is too high?', '[{"id":"A","text":"Insulin is released and glucose is moved into cells and stored as glycogen"},{"id":"B","text":"Glucagon is released to raise it further"},{"id":"C","text":"Adrenaline is released"},{"id":"D","text":"The kidneys make more glucose"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('dc865c5f-135b-5465-bab9-4588b29d00f6', 'A', 'Insulin causes cells to take in glucose, and the liver and muscles store it as glycogen.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('4a43fb59-e066-5303-bcc0-7f2cfaa90391', '7eca6fef-c4a6-51b7-8711-6360a53fa84e', 'short_answer', 'What is the name of the junction between two neurones?', null, 'standard', 'question_bank', true)
