on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('8443c70a-4739-5b67-b285-80839d63ef22', '7eca6fef-c4a6-51b7-8711-6360a53fa84e', 'multiple_choice', 'How is type 1 diabetes different from type 2?', '[{"id":"A","text":"In type 1 the pancreas produces little or no insulin; in type 2 the body''s cells no longer respond properly to insulin"},{"id":"B","text":"Type 1 is caused by eating too much sugar"},{"id":"C","text":"Type 2 is always treated with insulin injections"},{"id":"D","text":"There is no difference"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('8443c70a-4739-5b67-b285-80839d63ef22', 'A', 'Type 1 is usually treated with insulin. Type 2 is often linked to obesity and managed with diet, exercise and sometimes medicine.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('80630fcc-6b28-58cb-8f79-83276b47d724', '7eca6fef-c4a6-51b7-8711-6360a53fa84e', 'multiple_choice', 'How do nervous responses compare with hormonal responses?', '[{"id":"A","text":"Nervous responses are faster and shorter-lasting; hormones act more slowly but for longer"},{"id":"B","text":"Hormones are faster and travel along neurones"},{"id":"C","text":"Both travel in the blood"},{"id":"D","text":"Nervous responses last for days"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('80630fcc-6b28-58cb-8f79-83276b47d724', 'A', 'Nerve impulses are electrical and very fast. Hormones are chemicals carried in the blood, so they act more slowly and their effects last longer.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;

