insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('2ed43133-f355-5c58-bb55-620bc35fdccc', 'cb6bc838-c0a7-52c1-b545-e93fec86d984', 'multiple_choice', 'What is an allele?', '[{"id":"A","text":"A different version of the same gene"},{"id":"B","text":"A type of cell"},{"id":"C","text":"A whole chromosome"},{"id":"D","text":"A protein"}]'::jsonb, 'foundation', 'question_bank', true)
