insert into public.question_answers (question_id, correct_option, explanation) values ('2ed43133-f355-5c58-bb55-620bc35fdccc', 'A', 'Genes can come in different forms called alleles. For example, a gene for eye colour may have several alleles.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('6f5b71a5-7e91-5709-924c-cf9ae1739ed3', 'cb6bc838-c0a7-52c1-b545-e93fec86d984', 'true_false', 'True or false: human body cells usually contain 23 pairs of chromosomes.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('6f5b71a5-7e91-5709-924c-cf9ae1739ed3', 'A', 'Body cells have 46 chromosomes in 23 pairs. Sex cells (gametes) have 23 single chromosomes.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('cded2bb9-7400-56b8-bbc3-43de3cc879af', 'cb6bc838-c0a7-52c1-b545-e93fec86d984', 'multiple_choice', 'Two parents are both Bb, where B (brown) is dominant to b. What is the probability their child is bb?', '[{"id":"A","text":"25%"},{"id":"B","text":"50%"},{"id":"C","text":"75%"},{"id":"D","text":"0%"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('cded2bb9-7400-56b8-bbc3-43de3cc879af', 'A', 'A Punnett square gives BB, Bb, Bb and bb. One out of four outcomes is bb, so the probability is 25%.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('9bfd2d8f-6416-5a9e-bf4a-1749cd5577c3', 'cb6bc838-c0a7-52c1-b545-e93fec86d984', 'multiple_choice', 'Which statement describes natural selection?', '[{"id":"A","text":"Individuals best suited to their environment are more likely to survive, breed and pass on their alleles"},{"id":"B","text":"Animals change their bodies during their lives to suit the environment"},{"id":"C","text":"Humans choose which animals breed"},{"id":"D","text":"All individuals in a species are identical"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('9bfd2d8f-6416-5a9e-bf4a-1749cd5577c3', 'A', 'Variation exists; those with helpful characteristics survive and reproduce, so those alleles become more common over generations.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('beee1fd5-890d-5569-97c2-eea43693a2d0', 'cb6bc838-c0a7-52c1-b545-e93fec86d984', 'short_answer', 'What word describes an organism with two identical alleles for a gene, such as BB or bb?', null, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, accepted_answers, explanation) values ('beee1fd5-890d-5569-97c2-eea43693a2d0', array['homozygous']::text[], 'Homozygous means two identical alleles. Heterozygous means two different alleles, such as Bb.')
on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('7469c847-6cdc-5e49-91e5-d93484ecb10d', 'cb6bc838-c0a7-52c1-b545-e93fec86d984', 'multiple_choice', 'How does the evolution of antibiotic-resistant bacteria support the theory of natural selection?', '[{"id":"A","text":"Resistant bacteria survive treatment and reproduce, so resistance spreads through the population"},{"id":"B","text":"Bacteria decide to become resistant"},{"id":"C","text":"Antibiotics give bacteria new DNA on purpose"},{"id":"D","text":"Resistant bacteria can''t reproduce"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('7469c847-6cdc-5e49-91e5-d93484ecb10d', 'A', 'A random mutation gives resistance. When antibiotics kill the others, the resistant ones survive and multiply: natural selection in action.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('9b0f129b-ddc4-5de9-a1ab-3997ae2e969c', 'cb6bc838-c0a7-52c1-b545-e93fec86d984', 'multiple_choice', 'In the three-domain system, which three domains are living things divided into?', '[{"id":"A","text":"Archaea, Bacteria and Eukaryota"},{"id":"B","text":"Plants, Animals and Fungi"},{"id":"C","text":"Kingdom, Phylum and Class"},{"id":"D","text":"Prokaryotes, Viruses and Plants"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('9b0f129b-ddc4-5de9-a1ab-3997ae2e969c', 'A', 'Carl Woese proposed the three-domain system using evidence from chemical analysis, which showed archaea are distinct from bacteria.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;

