insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('88a1c507-4cc9-5d7d-b07f-cea1ecc49e85', '39635c72-f41f-5973-99df-4aafec05dee5', 'multiple_choice', 'What is the relative formula mass (Mr) of water, H₂O? (H = 1, O = 16)', '[{"id":"A","text":"18"},{"id":"B","text":"17"},{"id":"C","text":"34"},{"id":"D","text":"16"}]'::jsonb, 'foundation', 'question_bank', true)
