insert into public.question_answers (question_id, correct_option, explanation) values ('88a1c507-4cc9-5d7d-b07f-cea1ecc49e85', 'A', 'Add the relative atomic masses: 2 × 1 + 16 = 18.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('8a9042ab-f538-52ae-8c71-0f703f2a5989', '39635c72-f41f-5973-99df-4aafec05dee5', 'multiple_choice', 'What does the law of conservation of mass state?', '[{"id":"A","text":"No atoms are lost or made in a chemical reaction, so the mass of products equals the mass of reactants"},{"id":"B","text":"Mass always increases in a reaction"},{"id":"C","text":"Gases have no mass"},{"id":"D","text":"Mass is lost as heat"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('8a9042ab-f538-52ae-8c71-0f703f2a5989', 'A', 'Atoms are rearranged, not created or destroyed. If a reaction seems to lose mass, a gas has usually escaped.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('82fda198-6255-5b62-8a23-e06296d6681c', '39635c72-f41f-5973-99df-4aafec05dee5', 'true_false', 'True or false: when magnesium burns in an open container, its mass appears to increase.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
