insert into public.question_answers (question_id, correct_option, explanation) values ('82fda198-6255-5b62-8a23-e06296d6681c', 'A', 'Magnesium combines with oxygen from the air to make magnesium oxide, so the solid gains the mass of the oxygen.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('0def7776-796c-5c98-83cf-f095982922dc', '39635c72-f41f-5973-99df-4aafec05dee5', 'multiple_choice', 'What is the Mr of carbon dioxide, CO₂? (C = 12, O = 16)', '[{"id":"A","text":"44"},{"id":"B","text":"28"},{"id":"C","text":"32"},{"id":"D","text":"40"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('0def7776-796c-5c98-83cf-f095982922dc', 'A', 'Add the relative atomic masses: 12 + 2 × 16 = 44.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('fe20c025-aa11-5c4b-a389-6d8bf81104c8', '39635c72-f41f-5973-99df-4aafec05dee5', 'multiple_choice', '25 g of salt is dissolved to make 0.5 dm³ of solution. What is the concentration?', '[{"id":"A","text":"50 g/dm³"},{"id":"B","text":"12.5 g/dm³"},{"id":"C","text":"25 g/dm³"},{"id":"D","text":"0.02 g/dm³"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('fe20c025-aa11-5c4b-a389-6d8bf81104c8', 'A', 'Concentration = mass ÷ volume = 25 g ÷ 0.5 dm³ = 50 g/dm³.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('7c59d6af-0ab2-5276-892c-035ecb903a61', '39635c72-f41f-5973-99df-4aafec05dee5', 'short_answer', 'How many moles are in 36 g of water? (Mr of H₂O = 18) Give the number only.', null, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, accepted_answers, explanation) values ('7c59d6af-0ab2-5276-892c-035ecb903a61', array['2', '2 mol', '2 moles']::text[], 'Moles = mass ÷ Mr = 36 ÷ 18 = 2 mol.')
on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('f567646d-c922-5eb8-819e-fc0327e13e5f', '39635c72-f41f-5973-99df-4aafec05dee5', 'multiple_choice', 'What is Avogadro''s constant?', '[{"id":"A","text":"6.02 × 10²³ particles per mole"},{"id":"B","text":"6.02 × 10⁻²³ particles per mole"},{"id":"C","text":"1.6 × 10⁻¹⁹ particles per mole"},{"id":"D","text":"3.0 × 10⁸ particles per mole"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('f567646d-c922-5eb8-819e-fc0327e13e5f', 'A', 'One mole of any substance contains 6.02 × 10²³ particles (atoms, molecules or ions).')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('5f309117-dd4d-544d-8ef9-5adbd498a631', '39635c72-f41f-5973-99df-4aafec05dee5', 'multiple_choice', '2Mg + O₂ → 2MgO. What mass of MgO is made from 48 g of magnesium? (Mg = 24, O = 16)', '[{"id":"A","text":"80 g"},{"id":"B","text":"40 g"},{"id":"C","text":"64 g"},{"id":"D","text":"96 g"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('5f309117-dd4d-544d-8ef9-5adbd498a631', 'A', '48 g ÷ 24 = 2 mol Mg, which makes 2 mol MgO. Mr of MgO is 40, so the mass is 2 × 40 = 80 g.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;

