insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('2f488e13-7f3e-54f2-a9d4-d20b7b4c8538', '49dde60e-88f8-5dae-9a1c-c08836dd3f3b', 'multiple_choice', 'Which gas is given off when a metal reacts with an acid?', '[{"id":"A","text":"Hydrogen"},{"id":"B","text":"Oxygen"},{"id":"C","text":"Carbon dioxide"},{"id":"D","text":"Chlorine"}]'::jsonb, 'foundation', 'question_bank', true)
