insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('f850063a-2507-52b9-b60f-4c1a7bdae3e7', '49dde60e-88f8-5dae-9a1c-c08836dd3f3b', 'true_false', 'True or false: potassium is more reactive than copper.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
