insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('c85cde21-a90b-5130-8123-c4ce79d808fa', '49dde60e-88f8-5dae-9a1c-c08836dd3f3b', 'multiple_choice', 'Which salt is made when hydrochloric acid reacts with sodium hydroxide?', '[{"id":"A","text":"Sodium chloride"},{"id":"B","text":"Sodium sulfate"},{"id":"C","text":"Sodium nitrate"},{"id":"D","text":"Hydrogen chloride"}]'::jsonb, 'standard', 'question_bank', true)
