insert into public.question_answers (question_id, correct_option, explanation) values ('c85cde21-a90b-5130-8123-c4ce79d808fa', 'A', 'Acid + alkali → salt + water. Hydrochloric acid makes chlorides, sulfuric acid makes sulfates and nitric acid makes nitrates.')
