insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('2e7caf7b-9190-57be-a356-27f953b836c3', '49dde60e-88f8-5dae-9a1c-c08836dd3f3b', 'multiple_choice', 'Why can iron be extracted from its oxide by heating it with carbon?', '[{"id":"A","text":"Carbon is more reactive than iron, so it takes the oxygen"},{"id":"B","text":"Iron is more reactive than carbon"},{"id":"C","text":"Carbon is a metal"},{"id":"D","text":"Heating alone always extracts metals"}]'::jsonb, 'standard', 'question_bank', true)
