insert into public.question_answers (question_id, correct_option, explanation) values ('2e7caf7b-9190-57be-a356-27f953b836c3', 'A', 'Carbon displaces less reactive metals from their oxides. Metals more reactive than carbon, such as aluminium, need electrolysis.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('226ff296-5385-57a1-8cf3-1d246ce9b57a', '49dde60e-88f8-5dae-9a1c-c08836dd3f3b', 'short_answer', 'In electrolysis, what is the name of the negative electrode?', null, 'standard', 'question_bank', true)
