insert into public.question_answers (question_id, accepted_answers, explanation) values ('226ff296-5385-57a1-8cf3-1d246ce9b57a', array['cathode', 'the cathode']::text[], 'The cathode is negative and attracts positive ions. The anode is positive and attracts negative ions.')
on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('d4619160-1724-5f92-9a51-e34580b94619', '49dde60e-88f8-5dae-9a1c-c08836dd3f3b', 'multiple_choice', 'In a reaction, a substance gains electrons. What has happened to it?', '[{"id":"A","text":"It has been reduced"},{"id":"B","text":"It has been oxidised"},{"id":"C","text":"It has been neutralised"},{"id":"D","text":"It has been displaced"}]'::jsonb, 'challenge', 'question_bank', true)
