insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('eef68c9d-f693-5146-8cb6-f2e066752f06', '49dde60e-88f8-5dae-9a1c-c08836dd3f3b', 'multiple_choice', 'During the electrolysis of molten lead bromide, what forms at the cathode?', '[{"id":"A","text":"Lead"},{"id":"B","text":"Bromine"},{"id":"C","text":"Hydrogen"},{"id":"D","text":"Oxygen"}]'::jsonb, 'challenge', 'question_bank', true)
