insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('dac4bee7-a205-585c-9873-1ce6398147b9', '152a4799-4e95-5452-bb11-83338657edb6', 'multiple_choice', 'Which change usually makes a reaction go faster?', '[{"id":"A","text":"Increasing the temperature"},{"id":"B","text":"Using larger lumps of solid"},{"id":"C","text":"Using a more dilute solution"},{"id":"D","text":"Cooling the reactants"}]'::jsonb, 'foundation', 'question_bank', true)
