insert into public.question_answers (question_id, correct_option, explanation) values ('dac4bee7-a205-585c-9873-1ce6398147b9', 'A', 'Higher temperatures make particles move faster, so they collide more often and with more energy.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('ed2af000-0ac0-5d29-91b0-8eac61dc632d', '152a4799-4e95-5452-bb11-83338657edb6', 'multiple_choice', 'What does a catalyst do?', '[{"id":"A","text":"Speeds up a reaction without being used up"},{"id":"B","text":"Slows down a reaction"},{"id":"C","text":"Becomes one of the products"},{"id":"D","text":"Changes the products made"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('ed2af000-0ac0-5d29-91b0-8eac61dc632d', 'A', 'A catalyst increases the rate and is unchanged at the end, so it can be used again.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('a0efd562-7ff8-5de9-a1ed-9b1c31a329ed', '152a4799-4e95-5452-bb11-83338657edb6', 'true_false', 'True or false: powdered marble reacts faster with acid than a single large lump of the same mass.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
