insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('fc860172-fd71-50d2-be25-7d22009cf886', '152a4799-4e95-5452-bb11-83338657edb6', 'multiple_choice', 'According to collision theory, what must happen for particles to react?', '[{"id":"A","text":"They must collide with at least the activation energy"},{"id":"B","text":"They must stop moving"},{"id":"C","text":"They must be in the solid state"},{"id":"D","text":"They must be at room temperature"}]'::jsonb, 'standard', 'question_bank', true)
