insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('cd5f1967-4111-59fa-bbd9-6ba490769453', '152a4799-4e95-5452-bb11-83338657edb6', 'multiple_choice', 'How does a catalyst increase the rate of reaction?', '[{"id":"A","text":"It provides a different reaction pathway with a lower activation energy"},{"id":"B","text":"It gives particles more energy"},{"id":"C","text":"It increases the temperature"},{"id":"D","text":"It increases the concentration"}]'::jsonb, 'standard', 'question_bank', true)
