insert into public.question_answers (question_id, accepted_answers, explanation) values ('910995a4-6a7d-5496-8b84-97388cee9613', array['activation energy', 'the activation energy']::text[], 'Activation energy is the energy barrier a collision must overcome for bonds to break and a reaction to happen.')
