insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('c227087e-9df0-5c8e-b82b-4cdf67e68cba', '152a4799-4e95-5452-bb11-83338657edb6', 'multiple_choice', '40 cm³ of gas is produced in 20 seconds. What is the mean rate of reaction?', '[{"id":"A","text":"2 cm³/s"},{"id":"B","text":"0.5 cm³/s"},{"id":"C","text":"800 cm³/s"},{"id":"D","text":"60 cm³/s"}]'::jsonb, 'challenge', 'question_bank', true)
