insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('6b1d0a0e-6403-581b-aeba-db4923e1f284', '152a4799-4e95-5452-bb11-83338657edb6', 'multiple_choice', 'A reversible reaction is at equilibrium in a closed system. What is true?', '[{"id":"A","text":"The forward and backward reactions happen at the same rate"},{"id":"B","text":"Both reactions have stopped"},{"id":"C","text":"Only the forward reaction is happening"},{"id":"D","text":"All the reactants have been used up"}]'::jsonb, 'challenge', 'question_bank', true)
