insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('9564e43f-7ac3-5278-b12f-bd48e9c040f1', 'e610c100-b15e-5812-aa0e-dd64984deecf', 'true_false', 'True or false: crude oil is a finite resource.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
