insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('aaeb821c-91ad-55ab-9c42-146b7db3ff71', 'e610c100-b15e-5812-aa0e-dd64984deecf', 'multiple_choice', 'As hydrocarbon molecules get longer, what happens to their viscosity?', '[{"id":"A","text":"It increases: they become thicker"},{"id":"B","text":"It decreases"},{"id":"C","text":"It stays the same"},{"id":"D","text":"They become gases"}]'::jsonb, 'standard', 'question_bank', true)
