insert into public.question_answers (question_id, correct_option, explanation) values ('aaeb821c-91ad-55ab-9c42-146b7db3ff71', 'A', 'Longer chains have stronger forces between molecules, so they''re more viscous, less flammable and have higher boiling points.')
