insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('d770df64-74fa-5f55-bd18-993d0d646654', 'e610c100-b15e-5812-aa0e-dd64984deecf', 'short_answer', 'What is the name of the process that breaks long-chain hydrocarbons into shorter, more useful ones?', null, 'standard', 'question_bank', true)
