insert into public.question_answers (question_id, accepted_answers, explanation) values ('d770df64-74fa-5f55-bd18-993d0d646654', array['cracking']::text[], 'Cracking (catalytic or steam) produces shorter alkanes for fuels and alkenes for making polymers.')
