insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('ce07dd97-fdf7-573f-a54d-fbc38a97d1fd', 'e610c100-b15e-5812-aa0e-dd64984deecf', 'multiple_choice', 'What is the test for an alkene?', '[{"id":"A","text":"Bromine water turns from orange to colourless"},{"id":"B","text":"Limewater turns milky"},{"id":"C","text":"A glowing splint relights"},{"id":"D","text":"Damp litmus paper is bleached"}]'::jsonb, 'challenge', 'question_bank', true)
