insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('20a49767-c4fe-56ff-b0fd-3372df5a9a01', 'e610c100-b15e-5812-aa0e-dd64984deecf', 'multiple_choice', 'What are the products of complete combustion of a hydrocarbon?', '[{"id":"A","text":"Carbon dioxide and water"},{"id":"B","text":"Carbon monoxide and water"},{"id":"C","text":"Carbon and hydrogen"},{"id":"D","text":"Methane and oxygen"}]'::jsonb, 'challenge', 'question_bank', true)
