insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('e9475e32-c89e-5419-a56e-16253cfe377f', '0cfc4bd3-3035-53c4-a4c4-4a9e30889c57', 'multiple_choice', 'What is the unit of force?', '[{"id":"A","text":"Newton (N)"},{"id":"B","text":"Joule (J)"},{"id":"C","text":"Watt (W)"},{"id":"D","text":"Kilogram (kg)"}]'::jsonb, 'foundation', 'question_bank', true)
