insert into public.question_answers (question_id, correct_option, explanation) values ('e9475e32-c89e-5419-a56e-16253cfe377f', 'A', 'Force is measured in newtons. Mass is measured in kilograms and energy in joules.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('607cf118-ad2f-5a3c-84f3-b68803acaf5a', '0cfc4bd3-3035-53c4-a4c4-4a9e30889c57', 'multiple_choice', 'A 5 kg mass is on Earth, where g = 10 N/kg. What is its weight?', '[{"id":"A","text":"50 N"},{"id":"B","text":"5 N"},{"id":"C","text":"0.5 N"},{"id":"D","text":"15 N"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('607cf118-ad2f-5a3c-84f3-b68803acaf5a', 'A', 'Weight = mass × gravitational field strength = 5 × 10 = 50 N.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('dbed4f71-c154-50a3-b059-933320cbc2b4', '0cfc4bd3-3035-53c4-a4c4-4a9e30889c57', 'true_false', 'True or false: if the resultant force on a moving object is zero, it keeps moving at the same speed in the same direction.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('dbed4f71-c154-50a3-b059-933320cbc2b4', 'A', 'This is Newton''s first law. A resultant force is needed to change an object''s speed or direction.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('3b54bb66-210c-50f9-9ed4-e729c1a0b8e1', '0cfc4bd3-3035-53c4-a4c4-4a9e30889c57', 'multiple_choice', 'A 1200 kg car accelerates at 2 m/s². What resultant force acts on it?', '[{"id":"A","text":"2400 N"},{"id":"B","text":"600 N"},{"id":"C","text":"1202 N"},{"id":"D","text":"24 000 N"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('3b54bb66-210c-50f9-9ed4-e729c1a0b8e1', 'A', 'Newton''s second law: F = m × a = 1200 × 2 = 2400 N.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('87177f27-b043-5051-9f2e-c41336f718b3', '0cfc4bd3-3035-53c4-a4c4-4a9e30889c57', 'multiple_choice', 'Stopping distance is the sum of which two distances?', '[{"id":"A","text":"Thinking distance and braking distance"},{"id":"B","text":"Reaction time and speed"},{"id":"C","text":"Braking distance and friction"},{"id":"D","text":"Speed and mass"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('87177f27-b043-5051-9f2e-c41336f718b3', 'A', 'Thinking distance depends on reaction time; braking distance depends on speed, brakes, tyres and road conditions.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('09e7695a-8396-50c1-936e-5bae04f6e994', '0cfc4bd3-3035-53c4-a4c4-4a9e30889c57', 'short_answer', 'A force of 10 N stretches a spring by 0.2 m. What is the spring constant in N/m? Give the number only.', null, 'standard', 'question_bank', true)
