on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('620a318f-1a08-59f3-890c-81c6e706390e', '0cfc4bd3-3035-53c4-a4c4-4a9e30889c57', 'multiple_choice', 'What is the momentum of a 60 kg runner moving at 5 m/s?', '[{"id":"A","text":"300 kg m/s"},{"id":"B","text":"12 kg m/s"},{"id":"C","text":"65 kg m/s"},{"id":"D","text":"750 kg m/s"}]'::jsonb, 'challenge', 'question_bank', true)
