insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('f1abe3d7-36de-530c-8165-ccab429fb43c', '0cfc4bd3-3035-53c4-a4c4-4a9e30889c57', 'multiple_choice', 'Which pair is an example of Newton''s third law?', '[{"id":"A","text":"You push on a wall and the wall pushes back on you with an equal and opposite force"},{"id":"B","text":"A car speeds up when the engine force increases"},{"id":"C","text":"A ball keeps rolling on ice"},{"id":"D","text":"Weight depends on gravitational field strength"}]'::jsonb, 'challenge', 'question_bank', true)
