insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('8c03492f-7967-5b8f-8575-069bc08bceef', 'f32dcad4-7530-51e5-a273-0ebe31787735', 'multiple_choice', 'What happens to light when it enters glass from air at an angle?', '[{"id":"A","text":"It slows down and bends towards the normal"},{"id":"B","text":"It speeds up and bends away from the normal"},{"id":"C","text":"It stops"},{"id":"D","text":"It turns into sound"}]'::jsonb, 'challenge', 'question_bank', true)
