insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('c50b7345-868e-5b47-b4be-8d6ab53a0307', 'de6704d5-1b5b-59fb-86da-6b4c8a72d25a', 'multiple_choice', 'Which of these metals is magnetic?', '[{"id":"A","text":"Iron"},{"id":"B","text":"Copper"},{"id":"C","text":"Aluminium"},{"id":"D","text":"Gold"}]'::jsonb, 'foundation', 'question_bank', true)
