insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('93048dcd-366e-567e-bcbf-ee7dad29064c', 'de6704d5-1b5b-59fb-86da-6b4c8a72d25a', 'multiple_choice', 'Which change would make an electromagnet stronger?', '[{"id":"A","text":"Adding more turns of wire to the coil"},{"id":"B","text":"Using a smaller current"},{"id":"C","text":"Removing the iron core"},{"id":"D","text":"Using fewer turns"}]'::jsonb, 'standard', 'question_bank', true)
