insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('e4223776-e65f-5e9b-8b5b-71283a8abd87', 'de6704d5-1b5b-59fb-86da-6b4c8a72d25a', 'multiple_choice', 'Which direction do magnetic field lines point outside a bar magnet?', '[{"id":"A","text":"From the north pole to the south pole"},{"id":"B","text":"From the south pole to the north pole"},{"id":"C","text":"Straight upwards"},{"id":"D","text":"Towards both poles at once"}]'::jsonb, 'standard', 'question_bank', true)
