insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('651db433-e18a-56a2-8f60-e234fde46300', 'de6704d5-1b5b-59fb-86da-6b4c8a72d25a', 'short_answer', 'What is the name of the rule used to work out the direction of the force in the motor effect?', null, 'standard', 'question_bank', true)
