on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('fbe30c1a-4c9e-577e-a2f3-a360126f66aa', 'de6704d5-1b5b-59fb-86da-6b4c8a72d25a', 'multiple_choice', 'A wire 0.5 m long carries a current of 4 A at right angles to a magnetic field of 0.2 T. What is the force on it?', '[{"id":"A","text":"0.4 N"},{"id":"B","text":"10 N"},{"id":"C","text":"1.6 N"},{"id":"D","text":"0.1 N"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('fbe30c1a-4c9e-577e-a2f3-a360126f66aa', 'A', 'F = B × I × L = 0.2 × 4 × 0.5 = 0.4 N.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('61a74e97-026c-5a62-93dd-169703801770', 'de6704d5-1b5b-59fb-86da-6b4c8a72d25a', 'multiple_choice', 'Why does the National Grid use step-up transformers to transmit electricity at high voltage?', '[{"id":"A","text":"A higher voltage means a lower current, so less energy is lost heating the cables"},{"id":"B","text":"High voltage is safer in homes"},{"id":"C","text":"It makes electricity travel faster"},{"id":"D","text":"Transformers create extra energy"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('61a74e97-026c-5a62-93dd-169703801770', 'A', 'For the same power, raising the voltage lowers the current, and heating losses depend on current. Step-down transformers then reduce the voltage for homes.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;

