insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('ac733691-0235-59f2-b6a1-a806b08a384f', '3eb948d1-0890-5109-855a-f8b6c2296461', 'multiple_choice', 'Which type of radiation is stopped by a sheet of paper?', '[{"id":"A","text":"Alpha"},{"id":"B","text":"Beta"},{"id":"C","text":"Gamma"},{"id":"D","text":"None of them"}]'::jsonb, 'foundation', 'question_bank', true)
