insert into public.question_answers (question_id, correct_option, explanation) values ('ac733691-0235-59f2-b6a1-a806b08a384f', 'A', 'Alpha is stopped by paper or a few centimetres of air. Beta is stopped by thin aluminium; gamma needs thick lead or concrete.')
