insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('6c30ae89-5153-5d97-ad00-eb85125aa424', '3eb948d1-0890-5109-855a-f8b6c2296461', 'multiple_choice', 'What is an alpha particle made of?', '[{"id":"A","text":"2 protons and 2 neutrons"},{"id":"B","text":"An electron"},{"id":"C","text":"An electromagnetic wave"},{"id":"D","text":"1 proton and 1 neutron"}]'::jsonb, 'foundation', 'question_bank', true)
