insert into public.question_answers (question_id, correct_option, explanation) values ('6c30ae89-5153-5d97-ad00-eb85125aa424', 'A', 'An alpha particle is the same as a helium nucleus: two protons and two neutrons.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('904ce212-f2cb-5d17-8e75-c426b512cab6', '3eb948d1-0890-5109-855a-f8b6c2296461', 'true_false', 'True or false: radioactive decay is random.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
