insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('96c78f6a-6241-58e6-bde6-46dd94f9892c', '3eb948d1-0890-5109-855a-f8b6c2296461', 'multiple_choice', 'A sample has a half-life of 2 hours and an activity of 800 Bq. What is its activity after 6 hours?', '[{"id":"A","text":"100 Bq"},{"id":"B","text":"200 Bq"},{"id":"C","text":"400 Bq"},{"id":"D","text":"0 Bq"}]'::jsonb, 'standard', 'question_bank', true)
