insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('72974209-93f4-589a-92e9-6bfdfe4e7f95', '3eb948d1-0890-5109-855a-f8b6c2296461', 'multiple_choice', 'What is the difference between contamination and irradiation?', '[{"id":"A","text":"Contamination means radioactive material gets onto or into an object; irradiation means it''s exposed to radiation from outside"},{"id":"B","text":"They mean the same thing"},{"id":"C","text":"Irradiation makes an object radioactive"},{"id":"D","text":"Contamination only happens with gamma rays"}]'::jsonb, 'standard', 'question_bank', true)
