insert into public.question_answers (question_id, correct_option, explanation) values ('72974209-93f4-589a-92e9-6bfdfe4e7f95', 'A', 'An irradiated object doesn''t become radioactive. Contamination is harder to deal with because the source stays on or in the object.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('3266dc9f-9c82-5814-9333-26c41c4f833b', '3eb948d1-0890-5109-855a-f8b6c2296461', 'short_answer', 'What is the name for the time it takes for the number of radioactive nuclei in a sample to halve?', null, 'standard', 'question_bank', true)
