insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('08745864-c885-59f2-9bb6-451b472cb50c', '41b04283-8eac-568f-befe-eca305e17fc3', 'multiple_choice', 'Why are noble gases unreactive?', '[{"id":"A","text":"They have a full outer shell of electrons"},{"id":"B","text":"They are metals"},{"id":"C","text":"They have no electrons"},{"id":"D","text":"They are liquids"}]'::jsonb, 'foundation', 'question_bank', true)
