insert into public.question_answers (question_id, correct_option, explanation) values ('08745864-c885-59f2-9bb6-451b472cb50c', 'A', 'With a stable, full outer shell, noble gases don''t easily gain, lose or share electrons.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('a2009767-c78f-5bed-b2a7-3d8b1888efbf', '41b04283-8eac-568f-befe-eca305e17fc3', 'true_false', 'True or false: elements in the same group have the same number of electrons in their outer shell.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
