insert into public.question_answers (question_id, correct_option, explanation) values ('a2009767-c78f-5bed-b2a7-3d8b1888efbf', 'A', 'That is why elements in a group react in similar ways. The group number tells you the number of outer electrons (for groups 1 to 7).')
