insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('9d32546f-e613-5fde-a2fe-4b889fbd50b8', '41b04283-8eac-568f-befe-eca305e17fc3', 'multiple_choice', 'Which is the most reactive of these alkali metals?', '[{"id":"A","text":"Potassium"},{"id":"B","text":"Lithium"},{"id":"C","text":"Sodium"},{"id":"D","text":"They are all equally reactive"}]'::jsonb, 'standard', 'question_bank', true)
