insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('2425d5a3-b350-5a49-a64c-a8812fe3c7bb', '41b04283-8eac-568f-befe-eca305e17fc3', 'multiple_choice', 'Chlorine is bubbled into potassium bromide solution. What happens?', '[{"id":"A","text":"Chlorine displaces bromine because chlorine is more reactive"},{"id":"B","text":"Nothing happens"},{"id":"C","text":"Bromine displaces chlorine"},{"id":"D","text":"Potassium is displaced"}]'::jsonb, 'standard', 'question_bank', true)
