insert into public.question_answers (question_id, correct_option, explanation) values ('2425d5a3-b350-5a49-a64c-a8812fe3c7bb', 'A', 'A more reactive halogen displaces a less reactive one from its salt. Reactivity decreases down group 7.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('069d1a1b-eddb-57a2-a5c2-8c911de1449f', '41b04283-8eac-568f-befe-eca305e17fc3', 'short_answer', 'Which scientist arranged the elements in a table in 1869 and left gaps for undiscovered elements?', null, 'standard', 'question_bank', true)
