insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('4b5eee59-3945-52df-8cbe-c406caf7b680', '41b04283-8eac-568f-befe-eca305e17fc3', 'multiple_choice', 'Why does reactivity decrease down group 7?', '[{"id":"A","text":"The outer shell is further from the nucleus, so it''s harder to gain an electron"},{"id":"B","text":"The atoms lose electrons more easily"},{"id":"C","text":"The nucleus has fewer protons"},{"id":"D","text":"The elements become metals"}]'::jsonb, 'challenge', 'question_bank', true)
