insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('e9c137c4-8fe6-51a4-835c-a97e98b4a263', '41b04283-8eac-568f-befe-eca305e17fc3', 'multiple_choice', 'What are the products when sodium reacts with water?', '[{"id":"A","text":"Sodium hydroxide and hydrogen"},{"id":"B","text":"Sodium oxide and oxygen"},{"id":"C","text":"Sodium chloride and water"},{"id":"D","text":"Sodium carbonate and carbon dioxide"}]'::jsonb, 'challenge', 'question_bank', true)
