insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('287c3615-490c-58ad-83bc-ce6fdd333c8c', 'edcb67dc-7a2b-59ea-ba03-a449e20f5cab', 'multiple_choice', 'Who won the Battle of Hastings in 1066?', '[{"id":"A","text":"William of Normandy"},{"id":"B","text":"Harold Godwinson"},{"id":"C","text":"Harald Hardrada"},{"id":"D","text":"Edward the Confessor"}]'::jsonb, 'foundation', 'question_bank', true)
