insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('23cf37cc-e126-555e-be5e-9a5e2694a83d', 'edcb67dc-7a2b-59ea-ba03-a449e20f5cab', 'multiple_choice', 'What was the Domesday Book?', '[{"id":"A","text":"A survey of land and resources in England ordered by William in 1085"},{"id":"B","text":"A book of laws"},{"id":"C","text":"A religious text"},{"id":"D","text":"A list of Norman knights"}]'::jsonb, 'foundation', 'question_bank', true)
