insert into public.question_answers (question_id, correct_option, explanation) values ('23cf37cc-e126-555e-be5e-9a5e2694a83d', 'A', 'The Domesday survey recorded who held land and what it was worth, so William knew what taxes he could raise.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('78663bac-ea02-517b-9b01-f96021978e16', 'edcb67dc-7a2b-59ea-ba03-a449e20f5cab', 'true_false', 'True or false: early Norman castles were often motte-and-bailey castles built of earth and wood.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
