insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('b1cc2974-bd34-5e9c-b4b5-95c4c7946d27', 'edcb67dc-7a2b-59ea-ba03-a449e20f5cab', 'multiple_choice', 'Which battle did Harold Godwinson win shortly before Hastings?', '[{"id":"A","text":"Stamford Bridge"},{"id":"B","text":"Fulford Gate"},{"id":"C","text":"Bosworth"},{"id":"D","text":"Agincourt"}]'::jsonb, 'standard', 'question_bank', true)
