insert into public.question_answers (question_id, correct_option, explanation) values ('b1cc2974-bd34-5e9c-b4b5-95c4c7946d27', 'A', 'Harold defeated Harald Hardrada at Stamford Bridge in September 1066, then marched south to face William.')
