insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('72619cc4-ce7e-54ca-914c-480e484043f6', 'edcb67dc-7a2b-59ea-ba03-a449e20f5cab', 'multiple_choice', 'What was the Harrying of the North (1069–70)?', '[{"id":"A","text":"William''s destruction of land, crops and livestock in the north of England to crush rebellion"},{"id":"B","text":"A Viking invasion"},{"id":"C","text":"A peace treaty with Scotland"},{"id":"D","text":"The building of Durham Cathedral"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('72619cc4-ce7e-54ca-914c-480e484043f6', 'A', 'After rebellions in the north, William''s forces destroyed villages and food supplies. Many people died of famine.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('a9279dd7-5e60-5915-908f-9b1828b49cf7', 'edcb67dc-7a2b-59ea-ba03-a449e20f5cab', 'short_answer', 'What was the name of the system in which the king granted land to nobles in return for loyalty and military service?', null, 'standard', 'question_bank', true)
