insert into public.question_answers (question_id, accepted_answers, explanation) values ('a9279dd7-5e60-5915-908f-9b1828b49cf7', array['feudal system', 'the feudal system', 'feudalism']::text[], 'In the feudal system, land passed down from the king to tenants-in-chief, knights and peasants, each owing service to those above them.')
on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('702e5f7c-680b-5b56-8763-2026ce137e82', 'edcb67dc-7a2b-59ea-ba03-a449e20f5cab', 'multiple_choice', 'Why was William''s victory at Hastings helped by Harold''s march north?', '[{"id":"A","text":"Harold''s army was tired and had lost men after fighting at Stamford Bridge and marching back south"},{"id":"B","text":"Harold refused to fight"},{"id":"C","text":"William had a larger navy on the battlefield"},{"id":"D","text":"Harold was already dead"}]'::jsonb, 'challenge', 'question_bank', true)
