insert into public.question_answers (question_id, correct_option, explanation) values ('702e5f7c-680b-5b56-8763-2026ce137e82', 'A', 'Harold''s troops fought two major battles within weeks, with a long march between them, while William landed unopposed.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('8f98a930-eaf2-514b-85c6-20b6e2b2dae5', 'edcb67dc-7a2b-59ea-ba03-a449e20f5cab', 'multiple_choice', 'How did the Normans change the Church in England?', '[{"id":"A","text":"They replaced Anglo-Saxon bishops with Normans and rebuilt many cathedrals in stone"},{"id":"B","text":"They abolished the Church"},{"id":"C","text":"They made England Protestant"},{"id":"D","text":"They kept every Anglo-Saxon bishop"}]'::jsonb, 'challenge', 'question_bank', true)
