insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('2856deef-452f-5196-a674-976a63e80494', '842a43cc-713b-5027-bf2b-ed4a57ca158f', 'multiple_choice', 'Who was Elizabeth I''s Catholic cousin, executed in 1587?', '[{"id":"A","text":"Mary, Queen of Scots"},{"id":"B","text":"Catherine of Aragon"},{"id":"C","text":"Lady Jane Grey"},{"id":"D","text":"Mary I"}]'::jsonb, 'foundation', 'question_bank', true)
