insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('65aee5ec-ce8b-5ee9-a935-0e4362c71b69', '842a43cc-713b-5027-bf2b-ed4a57ca158f', 'short_answer', 'Which minister ran Elizabeth''s spy network?', null, 'standard', 'question_bank', true)
