insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('a72a91aa-c15b-5203-a39c-06d62c8259d7', '842a43cc-713b-5027-bf2b-ed4a57ca158f', 'multiple_choice', 'Which was a cause of rising poverty in Elizabethan England?', '[{"id":"A","text":"Population growth, rising prices and enclosure of land"},{"id":"B","text":"The abolition of farming"},{"id":"C","text":"Very low prices for food"},{"id":"D","text":"The end of the wool trade overnight"}]'::jsonb, 'challenge', 'question_bank', true)
