insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('bd1a0471-dd04-550b-af78-7b3c9eb44b7f', 'b7ffdce2-5963-5852-9f53-78f96bfa7590', 'multiple_choice', 'Which two superpowers were the main rivals in the Cold War?', '[{"id":"A","text":"The USA and the USSR"},{"id":"B","text":"Britain and France"},{"id":"C","text":"Germany and Japan"},{"id":"D","text":"China and India"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('bd1a0471-dd04-550b-af78-7b3c9eb44b7f', 'A', 'The capitalist USA and the communist USSR competed for influence without fighting each other directly.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('fc5aa26c-429a-50dc-8619-60b862223566', 'b7ffdce2-5963-5852-9f53-78f96bfa7590', 'multiple_choice', 'In which year was the Berlin Wall built?', '[{"id":"A","text":"1961"},{"id":"B","text":"1945"},{"id":"C","text":"1989"},{"id":"D","text":"1949"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('fc5aa26c-429a-50dc-8619-60b862223566', 'A', 'East Germany built the wall in August 1961 to stop people escaping to West Berlin. It came down in 1989.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('cc04f05d-59b8-5eca-8fab-a973d71c2ec4', 'b7ffdce2-5963-5852-9f53-78f96bfa7590', 'true_false', 'True or false: the USA and the USSR fought each other directly in a full-scale war during the Cold War.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('cc04f05d-59b8-5eca-8fab-a973d71c2ec4', 'B', 'It was "cold" because the superpowers never fought each other directly. They competed through arms races, alliances and proxy wars.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('c7b95a3b-ad39-5cde-bdab-1dd86a18354b', 'b7ffdce2-5963-5852-9f53-78f96bfa7590', 'multiple_choice', 'What was the Marshall Plan?', '[{"id":"A","text":"US economic aid to help rebuild Europe and stop the spread of communism"},{"id":"B","text":"A Soviet plan to take over Berlin"},{"id":"C","text":"A treaty to ban nuclear weapons"},{"id":"D","text":"A plan to divide Korea"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('c7b95a3b-ad39-5cde-bdab-1dd86a18354b', 'A', 'Announced in 1947, Marshall Aid gave billions of dollars to European countries. The USSR saw it as US "dollar imperialism".')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('01cd22c3-47d7-5279-99a9-55911462f611', 'b7ffdce2-5963-5852-9f53-78f96bfa7590', 'multiple_choice', 'How did the West respond to the Berlin Blockade of 1948–49?', '[{"id":"A","text":"The Berlin Airlift: supplies were flown into West Berlin"},{"id":"B","text":"An invasion of East Germany"},{"id":"C","text":"Building the Berlin Wall"},{"id":"D","text":"Giving West Berlin to the USSR"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('01cd22c3-47d7-5279-99a9-55911462f611', 'A', 'For about 11 months, planes flew food and fuel into West Berlin until Stalin lifted the blockade.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('7409ebaa-2476-5a12-ae94-fb0c8e902620', 'b7ffdce2-5963-5852-9f53-78f96bfa7590', 'short_answer', 'Which Caribbean island was at the centre of a 1962 crisis over Soviet nuclear missiles?', null, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, accepted_answers, explanation) values ('7409ebaa-2476-5a12-ae94-fb0c8e902620', array['cuba']::text[], 'During the Cuban Missile Crisis the world came close to nuclear war. It ended when the USSR agreed to remove the missiles.')
on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('dfde2f11-1b3a-5fc5-a45b-3f391216401e', 'b7ffdce2-5963-5852-9f53-78f96bfa7590', 'multiple_choice', 'What was the Truman Doctrine (1947)?', '[{"id":"A","text":"A US policy of supporting countries resisting communism (containment)"},{"id":"B","text":"A Soviet promise to leave Eastern Europe"},{"id":"C","text":"An agreement to share nuclear secrets"},{"id":"D","text":"A plan to unite Germany"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('dfde2f11-1b3a-5fc5-a45b-3f391216401e', 'A', 'Truman said the USA would help free peoples resist communism, starting with aid to Greece and Turkey.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('f4813e60-9234-57de-af18-1bd384919dc9', 'b7ffdce2-5963-5852-9f53-78f96bfa7590', 'multiple_choice', 'What did the 1963 Hotline Agreement and Limited Test Ban Treaty show after the Cuban Missile Crisis?', '[{"id":"A","text":"The superpowers wanted to reduce the risk of nuclear war"},{"id":"B","text":"The Cold War had ended"},{"id":"C","text":"The USSR had won the arms race"},{"id":"D","text":"Both sides would scrap all nuclear weapons"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('f4813e60-9234-57de-af18-1bd384919dc9', 'A', 'The crisis showed how dangerous misunderstandings could be. A direct phone link and limits on testing began a period of détente.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;

-- geography / Coasts
insert into public.topics (id, subject_id, slug, name, description, education_stage, sort_order)
select 'f20995a1-73b0-5d0b-82c4-c2dce004e716', id, 'coasts', 'Coasts', 'Coastal processes, erosional and depositional landforms, and management.', 'gcse', 510
from public.subjects where slug = 'geography'
on conflict (id) do update set name = excluded.name, description = excluded.description;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('6d253c2b-4bb3-589f-b45a-f6e2cbef39f5', 'f20995a1-73b0-5d0b-82c4-c2dce004e716', 'multiple_choice', 'Which type of wave has a strong backwash and erodes the coast?', '[{"id":"A","text":"Destructive wave"},{"id":"B","text":"Constructive wave"},{"id":"C","text":"Tidal wave"},{"id":"D","text":"Standing wave"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('6d253c2b-4bb3-589f-b45a-f6e2cbef39f5', 'A', 'Destructive waves are tall and frequent, with backwash stronger than swash. Constructive waves build beaches.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('70f09b0f-e7be-533e-8176-59c5c4629072', 'f20995a1-73b0-5d0b-82c4-c2dce004e716', 'multiple_choice', 'What is longshore drift?', '[{"id":"A","text":"The movement of sediment along a coast by waves"},{"id":"B","text":"The erosion of cliffs by rain"},{"id":"C","text":"The flooding of low land"},{"id":"D","text":"The movement of rivers into the sea"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('70f09b0f-e7be-533e-8176-59c5c4629072', 'A', 'Waves approach at an angle with the prevailing wind, then backwash pulls material straight back, zig-zagging sediment along the beach.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('c6059b17-6614-553a-90e1-3ae60e1caa88', 'f20995a1-73b0-5d0b-82c4-c2dce004e716', 'true_false', 'True or false: a spit is a landform made by deposition.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('c6059b17-6614-553a-90e1-3ae60e1caa88', 'A', 'Spits form where longshore drift carries sediment past a bend in the coastline and deposits it out into the sea.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('488f7a75-d43d-5ae1-8cf1-fe5277a23a30', 'f20995a1-73b0-5d0b-82c4-c2dce004e716', 'multiple_choice', 'What is the correct order of erosion at a headland?', '[{"id":"A","text":"Crack, cave, arch, stack, stump"},{"id":"B","text":"Stack, arch, cave, stump, crack"},{"id":"C","text":"Cave, crack, stump, arch, stack"},{"id":"D","text":"Arch, cave, crack, stack, stump"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('488f7a75-d43d-5ae1-8cf1-fe5277a23a30', 'A', 'Waves erode a crack into a cave, then through the headland into an arch. The arch collapses to leave a stack, which erodes into a stump.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('c6af97ad-a5d3-57dd-976a-269c1b1f9dab', 'f20995a1-73b0-5d0b-82c4-c2dce004e716', 'multiple_choice', 'Which of these is an example of hard engineering on the coast?', '[{"id":"A","text":"A sea wall"},{"id":"B","text":"Beach nourishment"},{"id":"C","text":"Managed retreat"},{"id":"D","text":"Dune regeneration"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('c6af97ad-a5d3-57dd-976a-269c1b1f9dab', 'A', 'Hard engineering uses built structures such as sea walls, groynes and rock armour. Soft engineering works with natural processes.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('4f012f6f-d061-5ad9-9e43-024994974dbe', 'f20995a1-73b0-5d0b-82c4-c2dce004e716', 'short_answer', 'What is the name of the erosion process in which waves force air into cracks in rock?', null, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, accepted_answers, explanation) values ('4f012f6f-d061-5ad9-9e43-024994974dbe', array['hydraulic action', 'hydraulic power']::text[], 'Hydraulic action compresses air in cracks. When the wave retreats the air expands, gradually breaking the rock apart.')
on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('7abf6975-33d8-5e38-87be-274fe9dcba87', 'f20995a1-73b0-5d0b-82c4-c2dce004e716', 'multiple_choice', 'Why might groynes built to protect one beach increase erosion further along the coast?', '[{"id":"A","text":"They trap sediment, so less is carried down-drift to protect beaches there"},{"id":"B","text":"They make waves stronger everywhere"},{"id":"C","text":"They cause sea levels to rise"},{"id":"D","text":"They stop longshore drift on all coasts"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('7abf6975-33d8-5e38-87be-274fe9dcba87', 'A', 'Groynes stop longshore drift locally, building that beach up. Beaches further along are starved of sediment and erode faster.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('a9c97b9d-9393-55df-bb80-7b9af28c2a2a', 'f20995a1-73b0-5d0b-82c4-c2dce004e716', 'multiple_choice', 'What is managed retreat?', '[{"id":"A","text":"Allowing an area of low-value land to flood, creating salt marsh that acts as a natural defence"},{"id":"B","text":"Building a taller sea wall"},{"id":"C","text":"Moving a whole city inland overnight"},{"id":"D","text":"Pumping sand onto a beach"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('a9c97b9d-9393-55df-bb80-7b9af28c2a2a', 'A', 'Removing defences lets the sea flood low-value land. The new salt marsh absorbs wave energy and creates habitats, but some land is lost.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;

-- geography / Climate change
insert into public.topics (id, subject_id, slug, name, description, education_stage, sort_order)
select 'beb0d72f-4800-5dca-ba8e-4c53113d3e8d', id, 'climate-change', 'Climate change', 'Evidence, natural and human causes, effects, mitigation and adaptation.', 'gcse', 520
from public.subjects where slug = 'geography'
on conflict (id) do update set name = excluded.name, description = excluded.description;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('576a1f34-2da3-5f7b-935a-227516daa4fa', 'beb0d72f-4800-5dca-ba8e-4c53113d3e8d', 'multiple_choice', 'Which gas released by burning fossil fuels is the main human cause of climate change?', '[{"id":"A","text":"Carbon dioxide"},{"id":"B","text":"Oxygen"},{"id":"C","text":"Nitrogen"},{"id":"D","text":"Helium"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('576a1f34-2da3-5f7b-935a-227516daa4fa', 'A', 'Burning coal, oil and gas releases carbon dioxide, which traps heat in the atmosphere and strengthens the greenhouse effect.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('d73f8a63-cbc5-5176-b121-61cb3cfd601e', 'beb0d72f-4800-5dca-ba8e-4c53113d3e8d', 'multiple_choice', 'Which of these is evidence that the climate is changing?', '[{"id":"A","text":"Shrinking glaciers and ice sheets"},{"id":"B","text":"Day and night"},{"id":"C","text":"The phases of the Moon"},{"id":"D","text":"Changing seasons each year"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('d73f8a63-cbc5-5176-b121-61cb3cfd601e', 'A', 'Retreating glaciers, rising sea levels and records of rising temperatures all show climate change.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('9ad53577-9bc3-5ed3-8a75-239d0fe732ef', 'beb0d72f-4800-5dca-ba8e-4c53113d3e8d', 'true_false', 'True or false: the greenhouse effect is natural, but human activity is making it stronger.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('9ad53577-9bc3-5ed3-8a75-239d0fe732ef', 'A', 'Without any greenhouse effect Earth would be far too cold for life. Extra greenhouse gases from humans are enhancing it.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('d03115fe-4972-59ca-ae79-8813a8003970', 'beb0d72f-4800-5dca-ba8e-4c53113d3e8d', 'multiple_choice', 'Which of these is a natural cause of climate change?', '[{"id":"A","text":"Volcanic eruptions"},{"id":"B","text":"Deforestation"},{"id":"C","text":"Car exhaust fumes"},{"id":"D","text":"Cattle farming"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('d03115fe-4972-59ca-ae79-8813a8003970', 'A', 'Large eruptions release ash and gases that can cool the Earth for a short time. Changes in Earth''s orbit and solar output are other natural causes.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('128010e4-71d5-53d2-a269-233384791385', 'beb0d72f-4800-5dca-ba8e-4c53113d3e8d', 'multiple_choice', 'What is the difference between mitigation and adaptation?', '[{"id":"A","text":"Mitigation reduces the causes of climate change; adaptation adjusts to its effects"},{"id":"B","text":"They mean the same thing"},{"id":"C","text":"Adaptation reduces emissions; mitigation builds flood defences"},{"id":"D","text":"Mitigation only happens in poorer countries"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('128010e4-71d5-53d2-a269-233384791385', 'A', 'Renewable energy and planting trees are mitigation. Building flood defences or growing drought-resistant crops are adaptation.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('070a6fde-7db3-555c-811d-c54221144ec0', 'beb0d72f-4800-5dca-ba8e-4c53113d3e8d', 'short_answer', 'Which gas, released by cattle and rice paddies, is a powerful greenhouse gas?', null, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, accepted_answers, explanation) values ('070a6fde-7db3-555c-811d-c54221144ec0', array['methane', 'ch4', 'ch₄']::text[], 'Methane traps much more heat per molecule than carbon dioxide, though it stays in the atmosphere for a shorter time.')
on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('85bd0ab2-103d-5b00-a830-3cedee859f71', 'beb0d72f-4800-5dca-ba8e-4c53113d3e8d', 'multiple_choice', 'What does carbon capture and storage involve?', '[{"id":"A","text":"Removing carbon dioxide from power station emissions and storing it underground"},{"id":"B","text":"Planting crops that need less water"},{"id":"C","text":"Building sea walls"},{"id":"D","text":"Burning more coal efficiently"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('85bd0ab2-103d-5b00-a830-3cedee859f71', 'A', 'CCS captures carbon dioxide before it reaches the atmosphere and stores it in old oil or gas fields. It''s expensive and still developing.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('af2405b1-3747-5fb7-a5f1-a0c0a19faefc', 'beb0d72f-4800-5dca-ba8e-4c53113d3e8d', 'multiple_choice', 'Why is ice core evidence useful for studying past climates?', '[{"id":"A","text":"Air bubbles trapped in the ice show past carbon dioxide levels and temperatures over hundreds of thousands of years"},{"id":"B","text":"Ice cores show tomorrow''s weather"},{"id":"C","text":"They only show the last 10 years"},{"id":"D","text":"They measure ocean depth"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('af2405b1-3747-5fb7-a5f1-a0c0a19faefc', 'A', 'Each layer of ice traps air from when it formed, giving a long record of how climate and greenhouse gases have changed.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;

-- geography / Urban issues and challenges
