insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('d82c95d8-9d23-59df-b481-8e39757af47b', '799588eb-4d6e-5970-840d-ec5f98da3bf2', 'multiple_choice', 'What is urbanisation?', '[{"id":"A","text":"An increase in the proportion of people living in towns and cities"},{"id":"B","text":"People moving from cities to the countryside"},{"id":"C","text":"Building new farms"},{"id":"D","text":"The growth of forests"}]'::jsonb, 'foundation', 'question_bank', true)
