insert into public.question_answers (question_id, correct_option, explanation) values ('d82c95d8-9d23-59df-b481-8e39757af47b', 'A', 'Urbanisation is happening fastest in lower-income and newly emerging countries, driven by migration and natural increase.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('19a0c5d2-1861-5519-ace3-e7ef2bfd46bc', '799588eb-4d6e-5970-840d-ec5f98da3bf2', 'multiple_choice', 'What is a megacity?', '[{"id":"A","text":"A city with more than 10 million people"},{"id":"B","text":"Any capital city"},{"id":"C","text":"A city with more than 1 million people"},{"id":"D","text":"A city with tall buildings"}]'::jsonb, 'foundation', 'question_bank', true)
