insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('29725e1e-9ec2-5740-9bd9-41420382264c', '799588eb-4d6e-5970-840d-ec5f98da3bf2', 'true_false', 'True or false: rural–urban migration is one cause of urban growth.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('29725e1e-9ec2-5740-9bd9-41420382264c', 'A', 'People move to cities for jobs, education and services (pull factors) and away from rural hardship (push factors).')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('f0444da8-545b-569e-9b47-34ed32301659', '799588eb-4d6e-5970-840d-ec5f98da3bf2', 'multiple_choice', 'Which is a push factor that might make someone leave a rural area?', '[{"id":"A","text":"A lack of jobs and services"},{"id":"B","text":"Better healthcare in the city"},{"id":"C","text":"More schools in the city"},{"id":"D","text":"Higher wages in the city"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('f0444da8-545b-569e-9b47-34ed32301659', 'A', 'Push factors drive people away from where they live. The other three are pull factors that attract people to cities.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('002f783b-fc73-5845-bec9-577e00ccc576', '799588eb-4d6e-5970-840d-ec5f98da3bf2', 'multiple_choice', 'What is an informal settlement (squatter settlement)?', '[{"id":"A","text":"An area of unplanned housing, often built illegally without proper services"},{"id":"B","text":"A planned housing estate"},{"id":"C","text":"A wealthy suburb"},{"id":"D","text":"A business district"}]'::jsonb, 'standard', 'question_bank', true)
