insert into public.question_answers (question_id, correct_option, explanation) values ('002f783b-fc73-5845-bec9-577e00ccc576', 'A', 'Informal settlements often lack clean water, sanitation and electricity. Many cities run upgrading schemes to improve them.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('68096d91-1daf-586f-ac31-9c0696e5ea9b', '799588eb-4d6e-5970-840d-ec5f98da3bf2', 'short_answer', 'What is the name for land that has been built on before and can be redeveloped?', null, 'standard', 'question_bank', true)
