insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('5418289f-acff-5220-b4b6-84da9aaa56e8', '799588eb-4d6e-5970-840d-ec5f98da3bf2', 'multiple_choice', 'Which feature would make a city more sustainable?', '[{"id":"A","text":"An integrated public transport system with cycle lanes"},{"id":"B","text":"More car parks in the centre"},{"id":"C","text":"Building on all green spaces"},{"id":"D","text":"Sending all waste to landfill"}]'::jsonb, 'challenge', 'question_bank', true)
