on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('b2c038ab-e463-58e9-85c2-121fbfcee627', '799588eb-4d6e-5970-840d-ec5f98da3bf2', 'multiple_choice', 'What is urban regeneration?', '[{"id":"A","text":"Investment to improve run-down areas of a city, such as old docks or industrial sites"},{"id":"B","text":"The natural growth of cities"},{"id":"C","text":"Moving people out of cities"},{"id":"D","text":"Building new cities from scratch"}]'::jsonb, 'challenge', 'question_bank', true)
