insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('8d5ae799-57f7-542e-bcdc-bc9a86c34249', '3dba090f-4cae-5596-94d9-ff02355c589e', 'multiple_choice', 'What does GNI per head measure?', '[{"id":"A","text":"The average income of people in a country"},{"id":"B","text":"The number of people in a country"},{"id":"C","text":"The size of a country"},{"id":"D","text":"The number of doctors per person"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('8d5ae799-57f7-542e-bcdc-bc9a86c34249', 'A', 'Gross National Income per head is a country''s total income divided by its population, so it gives an average.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('1dfc8297-b5b7-5e28-bcbc-27b5b3fde301', '3dba090f-4cae-5596-94d9-ff02355c589e', 'multiple_choice', 'Which of these is a social measure of development?', '[{"id":"A","text":"Life expectancy"},{"id":"B","text":"GNI per head"},{"id":"C","text":"Exports per year"},{"id":"D","text":"Energy use"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('1dfc8297-b5b7-5e28-bcbc-27b5b3fde301', 'A', 'Life expectancy, literacy rate and infant mortality show quality of life. GNI is an economic measure.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('0dea2c71-103a-5324-a552-2911c1d9f5d7', '3dba090f-4cae-5596-94d9-ff02355c589e', 'true_false', 'True or false: the Human Development Index (HDI) combines income, education and life expectancy.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('0dea2c71-103a-5324-a552-2911c1d9f5d7', 'A', 'HDI is a composite measure between 0 and 1. Because it combines several factors, it gives a fuller picture than income alone.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('0dc9a247-349d-55b0-8170-ea46e8b8a5e0', '3dba090f-4cae-5596-94d9-ff02355c589e', 'multiple_choice', 'What is the development gap?', '[{"id":"A","text":"The difference in standards of living between the world''s richest and poorest countries"},{"id":"B","text":"The distance between two countries"},{"id":"C","text":"The time it takes to build a road"},{"id":"D","text":"The difference between summer and winter temperatures"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('0dc9a247-349d-55b0-8170-ea46e8b8a5e0', 'A', 'The gap is shown by differences in income, health and education between higher-income and lower-income countries.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('eb9d3bd8-0109-59f4-a8c3-4ff6ea4a1be3', '3dba090f-4cae-5596-94d9-ff02355c589e', 'multiple_choice', 'Which of these is a way of reducing the development gap?', '[{"id":"A","text":"Fair trade, so farmers receive a fair price"},{"id":"B","text":"Higher trade barriers on poorer countries"},{"id":"C","text":"Increasing debt"},{"id":"D","text":"Reducing investment"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('eb9d3bd8-0109-59f4-a8c3-4ff6ea4a1be3', 'A', 'Fair trade, aid, investment, debt relief, microfinance and tourism can all help close the gap, each with strengths and weaknesses.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('49eede4c-e6a8-5fe6-bdc7-e953e7c7dde5', '3dba090f-4cae-5596-94d9-ff02355c589e', 'short_answer', 'What name is given to small loans made to people in poorer countries to start businesses?', null, 'standard', 'question_bank', true)
