insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('820d0039-2fe0-54db-836b-b0ab68a02d8b', '3dba090f-4cae-5596-94d9-ff02355c589e', 'multiple_choice', 'What is a transnational corporation (TNC)?', '[{"id":"A","text":"A company that operates in more than one country"},{"id":"B","text":"A government department for trade"},{"id":"C","text":"A charity that gives aid"},{"id":"D","text":"A country''s national bank"}]'::jsonb, 'challenge', 'question_bank', true)
