on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('530160ea-7e6e-5184-8877-d973c91bcae5', '3dba090f-4cae-5596-94d9-ff02355c589e', 'multiple_choice', 'Why might a country''s death rate fall as it develops?', '[{"id":"A","text":"Better healthcare, clean water and food supplies"},{"id":"B","text":"More people move away"},{"id":"C","text":"The birth rate rises"},{"id":"D","text":"Fewer people are counted"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('530160ea-7e6e-5184-8877-d973c91bcae5', 'A', 'In the demographic transition model, improvements in medicine, sanitation and diet bring the death rate down before the birth rate falls.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;

